window.KNOWLEDGE_DATA["chemistry-sp"] = {"subject":"chemistry","semester":"sp","stage":"special","label":"专题与压轴","chapters":[{"id":"chemistry-sp-c1","name":"工业工艺流程压轴","unit":"专题·工业工艺流程压轴","points":[{"id":"chemistry-sp-p01","name":"粗盐除可溶性杂质（Ca²⁺/Mg²⁺/SO4²⁻）与海水提镁","tag":"★","hasEssay":true,"card":{"concept":["除粗盐中 CaCl2、MgCl2、Na2SO4：分别加过量 Na2CO3（除 Ca²⁺ 及过量 Ba²⁺）、NaOH（除 Mg²⁺）、BaCl2（除 SO4²⁻），过滤后向滤液加适量稀盐酸（除过量 OH⁻、CO3²⁻），最后蒸发结晶。","三大试剂顺序铁律：Na2CO3 必须在 BaCl2 之后加入！稀盐酸必须在过滤之后加入！","海水提镁主线：海水(MgCl2) → 加熟石灰(Ca(OH)2)得 Mg(OH)2↓ → 加稀盐酸得 MgCl2 → 电解熔融 MgCl2 得 Mg＋Cl2↑。"],"formula":["合法加药顺序共 3 种：① BaCl2→NaOH→Na2CO3；② BaCl2→Na2CO3→NaOH；③ NaOH→BaCl2→Na2CO3。"],"pitfall":["若在过滤“之前”加稀盐酸，生成的 CaCO3、BaCO3、Mg(OH)2 沉淀会重新溶解，杂质又回到溶液里！"],"example":{"q":"如图粗盐提纯除可溶性杂质流程，为什么过量 Na2CO3 必须在过量 BaCl2 之后加入？","a":"Na2CO3 不仅要除去原溶液中的 Ca²⁺，还要把前面引入的过量 Ba²⁺ 转化为 BaCO3 沉淀一并除去。","img":"./assets/knowledge/chemistry/sp/p01-flow.svg"}},"qids":["kp-chemistry-sp-p01-01","kp-chemistry-sp-p01-02","kp-chemistry-sp-p01-03","kp-chemistry-sp-p01-04","kp-chemistry-sp-p01-05","kp-chemistry-sp-p01-06","kp-chemistry-sp-p01-07","kp-chemistry-sp-p01-08","kp-chemistry-sp-p01-09"],"refs":["national-js-suzhou-2026-chemistry-q23","national-jx-2026-chemistry-q17"]},{"id":"chemistry-sp-p02","name":"废液回收金属与矿石综合利用流程","tag":"★","hasEssay":true,"card":{"concept":["从含 CuSO4、FeSO4 的废液中回收金属铜并得 FeSO4 晶体：① 加“过量铁粉”（换出全部 Cu，不引新金属杂质）；② 过滤得滤渣（Cu＋过量 Fe）和滤液（FeSO4）；③ 滤渣加适量“稀硫酸”除过量 Fe，过滤洗净得纯 Cu！","流程常考三问：① 粉碎/搅拌/适当升温→增大接触面积、加快反应速率；② 过量试剂→使目标离子完全反应；③ 蒸发浓缩、冷却结晶→提取溶解度受温度影响大的晶体。"],"formula":["Fe＋CuSO4＝FeSO4＋Cu；Fe＋H2SO4＝FeSO4＋H2↑（切记用稀硫酸而不是稀盐酸，防引入 Cl⁻！）。"],"pitfall":["回收 FeSO4 晶体时，除过量铁粉必须用“稀硫酸”而绝不能用稀盐酸（否则引入 FeCl2 杂质）！"],"example":{"q":"从含 CuSO4 和 ZnSO4 的废液中回收金属铜和硫酸锌晶体，第一步应加入过量的哪种金属？","a":"加入过量锌粉（Zn＋CuSO4＝ZnSO4＋Cu），不引入新杂质；滤渣加稀硫酸除过量锌即可得纯铜。"}},"qids":["kp-chemistry-sp-p02-01","kp-chemistry-sp-p02-02","kp-chemistry-sp-p02-03","kp-chemistry-sp-p02-04","kp-chemistry-sp-p02-05","kp-chemistry-sp-p02-06","kp-chemistry-sp-p02-07","kp-chemistry-sp-p02-08","kp-chemistry-sp-p02-09"],"refs":["national-js-suzhou-2026-chemistry-q23","national-jx-2026-chemistry-q17"]},{"id":"chemistry-sp-p03","name":"碳捕集、双碳工艺与物质循环利用","tag":"★","card":{"concept":["“碳捕捉”典型工艺：捕捉室（2NaOH＋CO2＝Na2CO3＋H2O）→ 反应室（CaO＋H2O＝Ca(OH)2，Ca(OH)2＋Na2CO3＝CaCO3↓＋2NaOH）→ 高温煅烧炉（CaCO3＝(高温)CaO＋CO2↑）。","判断可循环利用物质：在流程图中，箭头指向前面步骤、既是后面反应的生成物又是前面反应的反应物（如碳捕捉中的 NaOH 和 CaO）！","双碳新途径：CO2 催化加氢制甲醇（CO2＋3H2＝CH3OH＋H2O），变废为宝实现碳资源化。"],"formula":["喷淋法吸收 CO2 优点：增大气体与碱液的接触面积，使 CO2 吸收更充分！"],"pitfall":["碳捕捉工艺中“喷淋”NaOH 溶液是增大接触面积；高温煅烧炉消耗大量能源是该工艺的主要缺点。"],"example":{"q":"如图“碳捕捉”工艺流程，整个过程中可以循环利用的两种物质是什么？","a":"氢氧化钠（NaOH）和氧化钙（CaO）。","img":"./assets/knowledge/chemistry/sp/p03-carbon.svg"}},"qids":["kp-chemistry-sp-p03-01","kp-chemistry-sp-p03-02","kp-chemistry-sp-p03-03","kp-chemistry-sp-p03-04","kp-chemistry-sp-p03-05","kp-chemistry-sp-p03-06","kp-chemistry-sp-p03-07","kp-chemistry-sp-p03-08"],"refs":["national-js-suzhou-2026-chemistry-q23","national-jx-2026-chemistry-q17"]}]},{"id":"chemistry-sp-c2","name":"框图推断与离子共存压轴","unit":"专题·框图推断与离子共存","points":[{"id":"chemistry-sp-p04","name":"题眼突破与初中常见“三角”转化框图推断","tag":"★","hasEssay":true,"card":{"concept":["必背颜色题眼：黑色固体（C、CuO、Fe3O4、MnO2、铁粉）；红色固体（Cu、Fe2O3 红棕）；蓝色溶液 Cu²⁺；浅绿色 Fe²⁺；黄色 Fe³⁺；蓝色沉淀 Cu(OH)2；红褐色沉淀 Fe(OH)3。","必背俗名/用途题眼：胃酸主要成分 HCl；建筑材料/补钙剂 CaCO3；改良酸性土壤 Ca(OH)2；焙制糕点 NaHCO3；光合作用原料 CO2/H2O。","三大高频三角：碳三角（C/CO/CO2）、氧三角（H2O2/H2O/O2）、钙三角（CaCO3/CaO/Ca(OH)2）。"],"formula":["元素组成相同气体：CO 与 CO2；元素组成相同液体：H2O2 与 H2O！"],"pitfall":["推出所有物质后，一定要把化学式全部代回原框图箭头逐条验算，确保每一步反应都能真实发生！"],"example":{"q":"如图钙三角：A 是大理石主要成分，高温分解得 B 和气体，B 与水反应剧烈放热得 C，C 通入 CO2 又变回 A。写出 A、B、C 化学式。","a":"A：CaCO3，B：CaO，C：Ca(OH)2。","img":"./assets/knowledge/chemistry/sp/p04-infer.svg"}},"qids":["kp-chemistry-sp-p04-01","kp-chemistry-sp-p04-02","kp-chemistry-sp-p04-03","kp-chemistry-sp-p04-04","kp-chemistry-sp-p04-05","kp-chemistry-sp-p04-06","kp-chemistry-sp-p04-07","kp-chemistry-sp-p04-08","kp-chemistry-sp-p04-09"],"refs":[]},{"id":"chemistry-sp-p05","name":"酸碱盐隐含条件（无色/pH/气体沉淀）离子共存压轴","tag":"★","card":{"concept":["审题先挖“隐含离子”：① pH＜7 / 遇石蕊变红 / 强酸性 → 隐含大量 H⁺；② pH＞7 / 遇酚酞变红 / 强碱性 → 隐含大量 OH⁻；③ 无色透明溶液 → 排除 Cu²⁺(蓝)、Fe²⁺(浅绿)、Fe³⁺(黄)、MnO4⁻(紫红)！","高频死对头离子清单：H⁺ 怕（OH⁻、CO3²⁻、HCO3⁻）；OH⁻ 怕（H⁺、NH4⁺、Mg²⁺、Fe³⁺、Cu²⁺、Al³⁺）；Ba²⁺ 怕（SO4²⁻、CO3²⁻）；Ca²⁺ 怕（CO3²⁻）；Ag⁺ 怕（Cl⁻、CO3²⁻、OH⁻）！"],"formula":["万能共存五剑客：K⁺、Na⁺、NO3⁻ 在初中水溶液中几乎不与任何离子反应！"],"pitfall":["看到“无色溶液”第一时间划掉含 Cu²⁺、Fe²⁺、Fe³⁺、MnO4⁻ 的选项！看到“pH＝13”立刻排除 NH4⁺、Mg²⁺、Cu²⁺、H⁺、HCO3⁻！"],"example":{"q":"在能使无色酚酞变红的溶液中，下列哪组离子能大量共存：A. NH4⁺、Na⁺、Cl⁻；B. K⁺、Na⁺、CO3²⁻、NO3⁻；C. H⁺、K⁺、SO4²⁻？","a":"选 B！酚酞变红隐含大量 OH⁻；A 中 NH4⁺＋OH⁻→NH3↑＋H2O，C 中 H⁺＋OH⁻→H2O，均不能共存。"}},"qids":["kp-chemistry-sp-p05-01","kp-chemistry-sp-p05-02","kp-chemistry-sp-p05-03","kp-chemistry-sp-p05-04","kp-chemistry-sp-p05-05","kp-chemistry-sp-p05-06","kp-chemistry-sp-p05-07","kp-chemistry-sp-p05-08"],"refs":[]},{"id":"chemistry-sp-p06","name":"金属与混合盐溶液滤渣滤液成分压轴","tag":"★","hasEssay":true,"card":{"concept":["核心法则：“弱者先出，强者后出”（远距离优先置换）！例如向 AgNO3、Cu(NO3)2 混合液加 Zn 粉：先发生 Zn＋2AgNO3→2Ag，Ag⁺ 耗尽后才发生 Zn＋Cu(NO3)2→Cu！","五段临界点（向 AgNO3、Cu(NO3)2 加 Fe 粉）：① Fe 极少（Ag⁺ 剩余）：渣 Ag，液 Fe²⁺/Cu²⁺/Ag⁺；② 恰好换完 Ag⁺：渣 Ag，液 Fe²⁺/Cu²⁺；③ 换部分 Cu²⁺：渣 Ag/Cu，液 Fe²⁺/Cu²⁺；④ 恰好换完 Cu²⁺：渣 Ag/Cu，液 Fe²⁺；⑤ Fe 过量：渣 Ag/Cu/Fe，液 Fe²⁺。","必有规律：滤渣中“一定有最不活泼的 Ag”；滤液中“一定有加入金属对应的盐（Fe(NO3)2）”！"],"formula":["检验技巧：向滤渣加稀盐酸有气泡 → 加入金属过量！向滤液加稀盐酸有白色沉淀（AgCl）→ AgNO3 剩余！"],"pitfall":["若滤液呈“蓝色”，说明 Cu(NO3)2 一定有剩余，此时加入的铁粉/锌粉肯定已完全耗尽（滤渣绝不含铁/锌），但 AgNO3 可能剩余也可能刚好耗尽！"],"example":{"q":"向 AgNO3 和 Cu(NO3)2 混合液中加入一定量铁粉，充分反应后过滤，若滤液呈浅绿色且向滤渣加稀盐酸无气泡，滤渣中一定有什么？可能有什么？","a":"滤液呈浅绿色说明 Cu²⁺ 已全部反应完（无蓝色），加盐酸无气泡说明 Fe 无剩余，故滤渣恰好是 Ag 和 Cu（两者一定都有，一定无 Fe）！"}},"qids":["kp-chemistry-sp-p06-01","kp-chemistry-sp-p06-02","kp-chemistry-sp-p06-03","kp-chemistry-sp-p06-04","kp-chemistry-sp-p06-05","kp-chemistry-sp-p06-06","kp-chemistry-sp-p06-07","kp-chemistry-sp-p06-08","kp-chemistry-sp-p06-09"],"refs":["national-js-suzhou-2026-chemistry-q19"]}]},{"id":"chemistry-sp-c3","name":"实验探究（变质/成分/除杂鉴别）压轴","unit":"专题·实验探究与除杂鉴别","points":[{"id":"chemistry-sp-p07","name":"氢氧化钠与生石灰变质程度探究（未变/部分/完全）","tag":"★","hasEssay":true,"card":{"concept":["NaOH 变质原因：2NaOH＋CO2＝Na2CO3＋H2O。检验是否变质（检 CO3²⁻）：加过量稀盐酸（看气泡）或 CaCl2/BaCl2 溶液（看白沉淀）或 Ca(OH)2（看白沉淀）。","探究变质程度（部分变质 NaOH＋Na2CO3 vs 完全变质 Na2CO3）两步铁律：① 加“过量”中性钙盐/钡盐（CaCl2 或 BaCl2）检验并“除尽”Na2CO3；② 静置取上层清液滴加无色酚酞（变红→部分变质；不变色→完全变质）！","生石灰（CaO）变质：先吸水变 Ca(OH)2（放热），再吸 CO2 变 CaCO3（加酸冒气泡）。"],"formula":["除杂（NaOH 溶液中除少量 Na2CO3）：加适量 Ca(OH)2 溶液过滤（Ca(OH)2＋Na2CO3＝CaCO3↓＋2NaOH）！"],"pitfall":["探究变质程度第一步绝不能用 Ca(OH)2 代替 CaCl2！因为 Ca(OH)2 与 Na2CO3 会新生成 NaOH，干扰原 NaOH 的检验！"],"example":{"q":"如图探究 NaOH 溶液变质程度，为什么第一步要加“过量”CaCl2 溶液而不是少量？","a":"确保将呈碱性的 Na2CO3 彻底转化为中性沉淀 CaCO3 除去，防止剩余 Na2CO3 使酚酞变红干扰 NaOH 检验。","img":"./assets/knowledge/chemistry/sp/p07-naoh.svg"}},"qids":["kp-chemistry-sp-p07-01","kp-chemistry-sp-p07-02","kp-chemistry-sp-p07-03","kp-chemistry-sp-p07-04","kp-chemistry-sp-p07-05","kp-chemistry-sp-p07-06","kp-chemistry-sp-p07-07","kp-chemistry-sp-p07-08","kp-chemistry-sp-p07-09"],"refs":[]},{"id":"chemistry-sp-p08","name":"反应后溶液中溶质成分猜想与验证","tag":"★","hasEssay":true,"card":{"concept":["溶质猜想黄金模型（A＋B → C＋沉淀/气体/水）：反应后溶液中“一定有生成物 C”，且反应物 A 和 B “绝不能同时剩余”（因为会继续反应！）。","故合理猜想只有三种：① 恰好完全反应（只有 C）；② A 过量（C＋A）；③ B 过量（C＋B）。","检验策略：不必再检验必有的生成物 C！只需选特征试剂分别检验“可能过量的 A”或“可能过量的 B”即可！"],"formula":["例：Ca(OH)2＋Na2CO3→CaCO3↓＋2NaOH，过滤后滤液溶质 3 猜想：① NaOH；② NaOH＋Ca(OH)2；③ NaOH＋Na2CO3。"],"pitfall":["检验 HCl＋NaOH 反应后是否剩余 HCl，不能用 AgNO3 溶液（因为生成的 NaCl 也含 Cl⁻，同样产生 AgCl 白沉淀！）——必须检验 H⁺（紫色石蕊、Zn 粒、Na2CO3、CuO）！"],"example":{"q":"CaCl2 溶液与 Na2CO3 溶液反应过滤后，某同学猜想滤液溶质为 NaCl、CaCl2 和 Na2CO3，该猜想合理吗？","a":"不合理！CaCl2 和 Na2CO3 在溶液中会继续反应生成 CaCO3 沉淀，不能共存。"}},"qids":["kp-chemistry-sp-p08-01","kp-chemistry-sp-p08-02","kp-chemistry-sp-p08-03","kp-chemistry-sp-p08-04","kp-chemistry-sp-p08-05","kp-chemistry-sp-p08-06","kp-chemistry-sp-p08-07","kp-chemistry-sp-p08-08","kp-chemistry-sp-p08-09"],"refs":[]},{"id":"chemistry-sp-p09","name":"多步除杂、无试剂鉴别与气体净化顺序","tag":"★","card":{"concept":["气体检验与除杂终极铁律：“检验先验水（无水 CuSO4 变蓝），除杂后除水（浓硫酸/碱石灰最后干燥）！”","气体净化洗气瓶口诀：“长进短出”！常见吸收剂：除 HCl 用饱和 NaHCO3（制 CO2 时）或水；除 CO2 用 NaOH 溶液；除 H2O 用浓硫酸（酸性/中性气体）或碱石灰（碱性/中性气体）。","无试剂鉴别法（两两混合法）：先看颜色（CuSO4 蓝、FeCl3 黄），再用已知色溶液去鉴别其他无色溶液（生成蓝色/红褐色沉淀或气体）。"],"formula":["CO2 中混有 HCl 和 H2O：先通饱和 NaHCO3 溶液除 HCl，再通浓硫酸干燥！"],"pitfall":["除去 CO2 中的 HCl 气体绝不能用 NaOH 溶液（会把 CO2 也吸收掉！），必须用饱和 NaHCO3 溶液（HCl＋NaHCO3＝NaCl＋H2O＋CO2↑）！"],"example":{"q":"如图，用大理石和浓盐酸制得的 CO2 中混有 HCl 气体和水蒸气，应先除 HCl 还是先除水蒸气？为什么？","a":"先通过饱和 NaHCO3 溶液除 HCl，再通过浓硫酸除水蒸气；若顺序颠倒，气体通过水溶液后又会重新带出水蒸气。","img":"./assets/knowledge/chemistry/sp/p09-gas.svg"}},"qids":["kp-chemistry-sp-p09-01","kp-chemistry-sp-p09-02","kp-chemistry-sp-p09-03","kp-chemistry-sp-p09-04","kp-chemistry-sp-p09-05","kp-chemistry-sp-p09-06","kp-chemistry-sp-p09-07","kp-chemistry-sp-p09-08"],"refs":[]}]},{"id":"chemistry-sp-c4","name":"化学图像与综合计算压轴","unit":"专题·图像分析与综合计算","points":[{"id":"chemistry-sp-p10","name":"复分解反应先后顺序与沉淀/气体拐点图像","tag":"★","hasEssay":true,"card":{"concept":["酸碱盐混合液滴加试剂“酸碱中和优先”铁律：① 向 HCl＋CuCl2（或 FeCl3/MgCl2）中滴加 NaOH → 先中和 HCl（无沉淀，起点延迟在横轴上！），HCl 耗尽后才生成 Cu(OH)2 沉淀！","② 向 HCl＋CaCl2 中滴加 Na2CO3 → 先与 HCl 反应产生 CO2 气体（无沉淀），HCl 耗尽后才生成 CaCO3 沉淀！","③ 向 NaOH＋Na2CO3 中滴加稀盐酸 → 先中和 NaOH（无气泡），NaOH 耗尽后才产生 CO2 气体！"],"formula":["图像三看：看起点（是否从原点出发）、看拐点（代表某反应恰好完全）、看平台（代表反应彻底结束）！"],"pitfall":["特例提醒：向 H2SO4＋HCl 中滴加 Ba(OH)2（或 BaCl2），由于 BaSO4 不溶于酸，白色沉淀会“立刻从原点（0 点）开始产生”，不会延迟！"],"example":{"q":"如图为向 HCl 和 CuCl2 混合溶液中逐滴加入 NaOH 溶液的沉淀质量变化曲线，ab 段和 bc 段分别发生什么反应？","a":"ab 段：NaOH＋HCl＝NaCl＋H2O（无沉淀）；bc 段：2NaOH＋CuCl2＝Cu(OH)2↓＋2NaCl。","img":"./assets/knowledge/chemistry/sp/p10-graph.svg"}},"qids":["kp-chemistry-sp-p10-01","kp-chemistry-sp-p10-02","kp-chemistry-sp-p10-03","kp-chemistry-sp-p10-04","kp-chemistry-sp-p10-05","kp-chemistry-sp-p10-06","kp-chemistry-sp-p10-07","kp-chemistry-sp-p10-08","kp-chemistry-sp-p10-09"],"refs":[]},{"id":"chemistry-sp-p11","name":"元素守恒法与差量法巧解化学计算","tag":"★","card":{"concept":["元素守恒法（极速秒杀多步复杂反应！）：若某元素全部从反应物转移到最终产物中，无需写中间每一步方程式，直接列“元素质量相等”即可！","例：Fe2O3 经多步反应全部转化为 FeSO4，铁元素守恒：Fe2O3 ～ 2Fe ～ 2FeSO4。","差量法：固液反应放出气体时，m(气体)＝m反应前总－m反应后总；金属置换盐溶液时，固体质量差 Δm 与金属质量成正比！"],"formula":["守恒核心：某元素质量＝化合物质量×该元素质量分数，反应前后恒等！"],"pitfall":["使用元素守恒必须确认该元素“100% 全部转移”到目标产物中，没有损耗或分配到其他副产物！"],"example":{"q":"某 FeO、Fe2O3、Fe3O4 的混合物共 10 g，用足量 CO 高温完全还原后得到纯铁 7.2 g，求反应中生成的 CO2 中所含来自氧化物的氧元素质量。","a":"混合物只含铁和氧，氧元素全部被 CO 夺走，故 m(O)＝10－7.2＝2.8 g。"}},"qids":["kp-chemistry-sp-p11-01","kp-chemistry-sp-p11-02","kp-chemistry-sp-p11-03","kp-chemistry-sp-p11-04","kp-chemistry-sp-p11-05","kp-chemistry-sp-p11-06","kp-chemistry-sp-p11-07","kp-chemistry-sp-p11-08"],"refs":["national-fj-2026-chemistry-q18","national-jx-2026-chemistry-q20"]},{"id":"chemistry-sp-p12","name":"溶液反应后所得溶液溶质质量分数综合计算","tag":"★","hasEssay":true,"card":{"concept":["中考最后一道压轴大题终极模板：求反应后所得溶液的溶质质量分数 ω＝[m(溶质)/m(反应后溶液)]×100%！","最容易算错的分母 m(反应后溶液) 必须用“质量守恒减法”：m(反应后溶液)＝反应前所有加入物质总质量 － 难溶杂质质量 － 生成的沉淀质量 － 生成的气体质量！","若生成物就是原有溶质（如 Na2CO3＋CaCl2 混有原 NaCl），分子别忘了加上原有的那部分溶质！"],"formula":["m液后＝m加入总 － m不溶杂 － m↓ － m↑；ω＝(m质后/m液后)×100%。"],"pitfall":["计算反应后溶液质量时，千万别忘了减去“不溶于水的杂质质量”以及“逸出的气体或生成的沉淀质量”！"],"example":{"q":"将 13 g 锌粒投入 100 g 稀硫酸中恰好完全反应（Zn-65, H2SO4-98, ZnSO4-161, H2-2），求反应后所得溶液的质量及溶质质量分数。","a":"13 g Zn（0.2 份）生成 0.4 g H2 和 32.2 g ZnSO4；m液后＝13＋100－0.4＝112.6 g；ω＝32.2/112.6≈28.6%。"}},"qids":["kp-chemistry-sp-p12-01","kp-chemistry-sp-p12-02","kp-chemistry-sp-p12-03","kp-chemistry-sp-p12-04","kp-chemistry-sp-p12-05","kp-chemistry-sp-p12-06","kp-chemistry-sp-p12-07","kp-chemistry-sp-p12-08","kp-chemistry-sp-p12-09"],"refs":[]}]}],"questions":[{"id":"kp-chemistry-sp-p01-01","subject":"chemistry","subjectLabel":"化学","knowledge":true,"kpId":"chemistry-sp-p01","kp":"粗盐除可溶性杂质（Ca²⁺/Mg²⁺/SO4²⁻）与海水提镁","unit":"专题·工业工艺流程压轴","chapter":"专题与压轴 · 工业工艺流程压轴","source":"知识点精练 · 专题与压轴 · 粗盐除可溶性杂质（Ca²⁺/Mg²⁺/SO4²⁻）与海水提镁（基础）","level":1,"kpFree":true,"image":"./assets/knowledge/chemistry/sp/p01-flow.svg","type":"single","stem":"如图粗盐精制除去 CaCl2、MgCl2、Na2SO4 的流程中，所加过量试剂的顺序错误的是（ ）","options":[{"key":"A","text":"Na2CO3 → BaCl2 → NaOH"},{"key":"B","text":"NaOH → BaCl2 → Na2CO3"},{"key":"C","text":"BaCl2 → Na2CO3 → NaOH"},{"key":"D","text":"BaCl2 → NaOH → Na2CO3"}],"answer":["A"],"explanation":"Na2CO3 必须在 BaCl2 之后加入才能除去过量 Ba²⁺，A 顺序错误。"},{"id":"kp-chemistry-sp-p01-02","subject":"chemistry","subjectLabel":"化学","knowledge":true,"kpId":"chemistry-sp-p01","kp":"粗盐除可溶性杂质（Ca²⁺/Mg²⁺/SO4²⁻）与海水提镁","unit":"专题·工业工艺流程压轴","chapter":"专题与压轴 · 工业工艺流程压轴","source":"知识点精练 · 专题与压轴 · 粗盐除可溶性杂质（Ca²⁺/Mg²⁺/SO4²⁻）与海水提镁（基础）","level":1,"kpFree":true,"image":"./assets/knowledge/chemistry/sp/p01-flow.svg","type":"single","stem":"如图粗盐精制流程，向滤液中加入适量稀盐酸的作用是（ ）","options":[{"key":"A","text":"除去过量的 BaCl2"},{"key":"B","text":"除去过量的 NaOH 和 Na2CO3"},{"key":"C","text":"除去泥沙"},{"key":"D","text":"增加氯离子"}],"answer":["B"],"explanation":"过滤后滤液中含过量 NaOH 和 Na2CO3，加稀盐酸反应转化为 NaCl、H2O 和 CO2。"},{"id":"kp-chemistry-sp-p01-03","subject":"chemistry","subjectLabel":"化学","knowledge":true,"kpId":"chemistry-sp-p01","kp":"粗盐除可溶性杂质（Ca²⁺/Mg²⁺/SO4²⁻）与海水提镁","unit":"专题·工业工艺流程压轴","chapter":"专题与压轴 · 工业工艺流程压轴","source":"知识点精练 · 专题与压轴 · 粗盐除可溶性杂质（Ca²⁺/Mg²⁺/SO4²⁻）与海水提镁（基础）","level":1,"kpFree":true,"type":"blank","stem":"粗盐精制加过量 BaCl2、NaOH、Na2CO3 充分反应后过滤，得到的滤渣中共有______种难溶沉淀。","blanks":[["4","四"]],"answer":["4"],"explanation":"沉淀共有 4 种：BaSO4、Mg(OH)2、CaCO3、BaCO3。"},{"id":"kp-chemistry-sp-p01-04","subject":"chemistry","subjectLabel":"化学","knowledge":true,"kpId":"chemistry-sp-p01","kp":"粗盐除可溶性杂质（Ca²⁺/Mg²⁺/SO4²⁻）与海水提镁","unit":"专题·工业工艺流程压轴","chapter":"专题与压轴 · 工业工艺流程压轴","source":"知识点精练 · 专题与压轴 · 粗盐除可溶性杂质（Ca²⁺/Mg²⁺/SO4²⁻）与海水提镁（提高）","level":2,"kpFree":true,"kpDiag":true,"type":"single","stem":"海水提镁流程：海水 → 加石灰乳沉淀 → 过滤 → 加稀盐酸溶解 → 浓缩结晶 → 电解熔融 MgCl2。加入石灰乳后生成的白色沉淀是（ ）","options":[{"key":"A","text":"CaCO3"},{"key":"B","text":"MgCO3"},{"key":"C","text":"Mg(OH)2"},{"key":"D","text":"BaSO4"}],"answer":["C"],"explanation":"MgCl2＋Ca(OH)2＝Mg(OH)2↓＋CaCl2。"},{"id":"kp-chemistry-sp-p01-05","subject":"chemistry","subjectLabel":"化学","knowledge":true,"kpId":"chemistry-sp-p01","kp":"粗盐除可溶性杂质（Ca²⁺/Mg²⁺/SO4²⁻）与海水提镁","unit":"专题·工业工艺流程压轴","chapter":"专题与压轴 · 工业工艺流程压轴","source":"知识点精练 · 专题与压轴 · 粗盐除可溶性杂质（Ca²⁺/Mg²⁺/SO4²⁻）与海水提镁（提高）","level":2,"kpFree":false,"type":"single","stem":"工业上粗盐精制时，如果把“过滤”和“加稀盐酸”两个步骤颠倒，造成的后果是（ ）","options":[{"key":"A","text":"BaSO4 沉淀溶解"},{"key":"B","text":"NaCl 质量减少"},{"key":"C","text":"没有影响"},{"key":"D","text":"CaCO3、BaCO3 和 Mg(OH)2 沉淀重新溶解，除杂失败"}],"answer":["D"],"explanation":"碳酸盐和氢氧化物沉淀均溶于稀盐酸，会导致杂质离子重新进入溶液。"},{"id":"kp-chemistry-sp-p01-06","subject":"chemistry","subjectLabel":"化学","knowledge":true,"kpId":"chemistry-sp-p01","kp":"粗盐除可溶性杂质（Ca²⁺/Mg²⁺/SO4²⁻）与海水提镁","unit":"专题·工业工艺流程压轴","chapter":"专题与压轴 · 工业工艺流程压轴","source":"知识点精练 · 专题与压轴 · 粗盐除可溶性杂质（Ca²⁺/Mg²⁺/SO4²⁻）与海水提镁（提高）","level":2,"kpFree":false,"type":"blank","stem":"在工业流程中，原料粉碎成细粉的目的是增大反应物之间的______，加快反应速率并使反应更充分。","blanks":[["接触面积"]],"answer":["接触面积"],"explanation":"固体粉碎可增大接触面积，提高反应速率和原料利用率。"},{"id":"kp-chemistry-sp-p01-07","subject":"chemistry","subjectLabel":"化学","knowledge":true,"kpId":"chemistry-sp-p01","kp":"粗盐除可溶性杂质（Ca²⁺/Mg²⁺/SO4²⁻）与海水提镁","unit":"专题·工业工艺流程压轴","chapter":"专题与压轴 · 工业工艺流程压轴","source":"知识点精练 · 专题与压轴 · 粗盐除可溶性杂质（Ca²⁺/Mg²⁺/SO4²⁻）与海水提镁（拓展）","level":3,"kpFree":false,"type":"single","stem":"若将粗盐精制中的“加过量 NaOH 和 BaCl2”合二为一，改用一种过量试剂即可同时除去 Mg²⁺ 和 SO4²⁻，该试剂是（ ）","options":[{"key":"A","text":"Ba(OH)2"},{"key":"B","text":"Ca(OH)2"},{"key":"C","text":"K2CO3"},{"key":"D","text":"AgNO3"}],"answer":["A"],"explanation":"Ba(OH)2 提供 Ba²⁺ 沉淀 SO4²⁻、提供 OH⁻ 沉淀 Mg²⁺，且过量 Ba²⁺ 可被后续 Na2CO3 除去。"},{"id":"kp-chemistry-sp-p01-08","subject":"chemistry","subjectLabel":"化学","knowledge":true,"kpId":"chemistry-sp-p01","kp":"粗盐除可溶性杂质（Ca²⁺/Mg²⁺/SO4²⁻）与海水提镁","unit":"专题·工业工艺流程压轴","chapter":"专题与压轴 · 工业工艺流程压轴","source":"知识点精练 · 专题与压轴 · 粗盐除可溶性杂质（Ca²⁺/Mg²⁺/SO4²⁻）与海水提镁（拓展）","level":3,"kpFree":false,"type":"single","stem":"海水提镁第一步将 MgCl2 转化为 Mg(OH)2 沉淀，第二步又加盐酸转回 MgCl2，看似多此一举，其实目的是（ ）","options":[{"key":"A","text":"产生氢气"},{"key":"B","text":"富集并提纯镁元素（将低浓度 MgCl2 从大量 NaCl 中分离出来）"},{"key":"C","text":"降低成本"},{"key":"D","text":"改变镁元素化合价"}],"answer":["B"],"explanation":"海水中 MgCl2 浓度极低且混有大量 NaCl，通过沉淀再溶解实现富集和提纯。"},{"id":"kp-chemistry-sp-p01-09","subject":"chemistry","subjectLabel":"化学","knowledge":true,"kpId":"chemistry-sp-p01","kp":"粗盐除可溶性杂质（Ca²⁺/Mg²⁺/SO4²⁻）与海水提镁","unit":"专题·工业工艺流程压轴","chapter":"专题与压轴 · 工业工艺流程压轴","source":"知识点精练 · 专题与压轴 · 粗盐除可溶性杂质（Ca²⁺/Mg²⁺/SO4²⁻）与海水提镁（压轴解答）","level":3,"kpFree":false,"type":"essay","meta":"工业工艺流程大题","stem":"粗盐中含有可溶性杂质 CaCl₂、MgCl₂、Na₂SO₄，精制流程如下：粗盐溶解 → 依次加入过量 BaCl₂ 溶液、过量 NaOH 溶液、过量 Na₂CO₃ 溶液 → 过滤 → 向滤液中加适量稀盐酸 → 蒸发结晶得精盐。（1）写出加入 Na₂CO₃ 溶液时发生的两个化学方程式；（2）向滤液中加适量稀盐酸的作用是什么？（3）为什么 Na₂CO₃ 溶液必须在 BaCl₂ 溶液之后加入？","score":10,"points":[{"text":"（1）CaCl₂＋Na₂CO₃＝CaCO₃↓＋2NaCl；BaCl₂＋Na₂CO₃＝BaCO₃↓＋2NaCl","score":4,"keys":["CaCO₃","CaCO3","BaCO₃","BaCO3"]},{"text":"（2）除去滤液中过量的 NaOH 和 Na₂CO₃（转化为 NaCl）","score":3,"keys":["NaOH","Na₂CO₃","Na2CO3","过量"]},{"text":"（3）Na₂CO₃ 可同时除去原杂质 Ca²⁺ 和前面过量的 Ba²⁺，若先加 Na₂CO₃ 则过量 BaCl₂ 无法除去，引入新杂质","score":3,"keys":["过量","Ba²⁺","BaCl₂","BaCl2","新杂质"]}],"method":"① 除杂试剂一一对应：BaCl₂ 除 SO₄²⁻，NaOH 除 Mg²⁺，Na₂CO₃ 同时除 Ca²⁺ 和过量 Ba²⁺；② 过滤后滤液里残留过量的 OH⁻ 和 CO₃²⁻，用稀盐酸一次中和成 NaCl、H₂O 和 CO₂；③ 试剂顺序唯一铁律：Na₂CO₃ 在 BaCl₂ 之后、稀盐酸在过滤之后。","sample":"解：（1）加入过量 Na₂CO₃ 溶液发生两个反应：\n① CaCl₂＋Na₂CO₃＝CaCO₃↓＋2NaCl；\n② BaCl₂＋Na₂CO₃＝BaCO₃↓＋2NaCl。\n（2）向滤液中加入适量稀盐酸的作用：除去滤液中过量的 NaOH 和 Na₂CO₃（得到纯净的 NaCl 溶液）。\n（3）原因：因为所加 BaCl₂ 是过量的，只有将 Na₂CO₃ 放在 BaCl₂ 之后加入，才能用 CO₃²⁻ 把过量的 Ba²⁺ 转化为 BaCO₃ 沉淀除去；若颠倒顺序，过量的 BaCl₂ 将无法除去，引入新的杂质。","explanation":"工艺流程常考加问：“蒸发结晶时盐酸稍过量有没有关系？”答：没关系，因为 HCl 易挥发，蒸发时会随水蒸气挥发除去。"},{"id":"national-js-suzhou-2026-chemistry-q23","national":true,"subject":"chemistry","subjectLabel":"化学","paperId":"js-suzhou-2026-chemistry","number":23,"section":"非选择题","chapter":"2026 年苏州中考化学","grade":"九下","stage":"9-down","source":"2026 年苏州中考化学 第 23 题","type":"essay","meta":"非选择题","material":"","stem":"（10 分）以某废酸（主要含 FeSO₄、H₂SO₄）为原料制磁性铁黑（Fe₃O₄）的流程：废酸 →（加碳酸钙）除酸 → 过滤 1（得滤渣）→（加熟石灰）沉铁 →（加 NaClO₃）氧化 → 过滤 2（得滤液）→ 磁选 → 磁性铁黑。已知：Fe(OH)₂、Fe(OH)₃ 难溶于水；CaSO₄ 微溶于水。\n(1) 若用 xFeO·yFe₂O₃ 表示 Fe₃O₄，则 x∶y＝______。\n(2)“除酸”步骤主要发生碳酸钙与 H₂SO₄ 的反应，充分反应后溶液 pH 约为 3。写出该反应的化学方程式：______。\n(3)“沉铁”步骤控制溶液 pH 在 8 左右，将 FeSO₄ 转化为 Fe(OH)₂。① FeSO₄ 与熟石灰反应的基本类型为______反应。② 熟石灰的作用除与 FeSO₄ 反应外，还有______。\n(4)“氧化”步骤发生两个反应：反应Ⅰ：6Fe(OH)₂＋NaClO₃＋3H₂O ═ 6Fe(OH)₃＋NaCl；反应Ⅱ：Fe(OH)₂＋2Fe(OH)₃ ═90 ℃═ Fe₃O₄＋4H₂O。溶液 pH 影响产品颜色与产率：pH 6.0 黄褐 43.9%；6.5 黄褐 50.6%；7.0 较黑 86.2%；7.5 很黑 93.0%；8.0 很黑 92.3%；9.0 灰黑 91.6%。① 该步骤最适宜的 pH 为______。② 保持最适宜的 pH，若增大“氧化”步骤 NaClO₃ 的用量（与理论用量相比），可提高磁性铁黑的产率。判断该说法是否合理，并说明理由：______。\n(5)“磁选”的目的是将 Fe₃O₄ 与其他杂质分离，该杂质主要为______。","points":[{"text":"(1) 1∶1","score":1,"keys":[]},{"text":"(2) CaCO₃＋H₂SO₄ ═ CaSO₄＋H₂O＋CO₂↑","score":2,"keys":[]},{"text":"(3)① 复分解","score":1,"keys":[]},{"text":"② 与残留的 H₂SO₄ 反应（或调节溶液 pH）","score":1,"keys":[]},{"text":"(4)① 7.5","score":1,"keys":[]},{"text":"② 否：NaClO₃ 增多，反应Ⅰ消耗的 Fe(OH)₂ 多、生成的 Fe(OH)₃ 多，参与反应Ⅱ的两者比例不当，产率下降","score":2,"keys":[]},{"text":"(5) CaSO₄","score":2,"keys":[]}],"score":10,"sample":"(1) 1∶1；(2) CaCO₃＋H₂SO₄ ═ CaSO₄＋H₂O＋CO₂↑；(3) ① 复分解；② 与残留的 H₂SO₄ 反应（或调节溶液 pH）；(4) ① 7.5；② 不合理。NaClO₃ 用量增大，反应Ⅰ消耗的 Fe(OH)₂ 多，生成的 Fe(OH)₃ 多，参与反应Ⅱ的 Fe(OH)₂ 与 Fe(OH)₃ 比例不当，磁性铁黑产率下降；(5) CaSO₄","method":"先写已知和所求，再列式计算，每一步写清依据，最后写结论。","answer":[],"explanation":"Fe₃O₄＝FeO·Fe₂O₃。除酸后 pH 约 3，仍有硫酸，熟石灰先中和它。反应Ⅱ需要 Fe(OH)₂∶Fe(OH)₃＝1∶2，氧化剂过量会把 Fe(OH)₂ 氧化得太多。CaSO₄ 微溶，会混在沉淀里，磁选把它分开。","kp":"工艺流程","image":"./assets/national/js-suzhou-2026-chemistry/q23.webp","kpId":"chemistry-sp-p01","kpRef":true},{"id":"national-jx-2026-chemistry-q17","national":true,"subject":"chemistry","subjectLabel":"化学","paperId":"jx-2026-chemistry","number":17,"section":"填空与说明题","chapter":"2026 年江西中考化学","grade":"九下","stage":"9-down","source":"2026 年江西中考化学 第 17 题","type":"essay","meta":"填空与说明题","material":"","stem":"（5 分）柠檬酸钙微溶于水，是一种安全的食品补钙剂。某学习小组以蛋壳为原料制备柠檬酸钙，主要过程：蛋壳（主要成分 CaCO₃）→ 研磨 → 蛋壳粉 →（加适量稀醋酸）操作① → 醋酸钙 (CH₃COO)₂Ca 溶液和滤渣；醋酸钙中加适量柠檬酸 → 过滤 → 柠檬酸钙（洗涤、干燥得产品）和物质 X。已知：醋酸的化学式为 CH₃COOH；柠檬酸与醋酸钙能发生复分解反应。\n(1) 研磨蛋壳的主要目的是______。\n(2) 将稀醋酸加入蛋壳粉中，反应生成醋酸钙、水和二氧化碳，该反应的化学方程式为______。\n(3) 进行操作①时，需使用的玻璃仪器有烧杯、玻璃棒和______。\n(4) 该实验中，可循环使用的物质是______。","points":[{"text":"(1) 增大反应物接触面积，加快反应速率","score":1,"keys":[]},{"text":"(2) 2CH₃COOH＋CaCO₃ ═ (CH₃COO)₂Ca＋CO₂↑＋H₂O","score":2,"keys":[]},{"text":"(3) 漏斗","score":1,"keys":[]},{"text":"(4) 稀醋酸","score":1,"keys":[]}],"score":5,"sample":"(1) 增大反应物接触面积，加快反应速率；(2) 2CH₃COOH＋CaCO₃ ═ (CH₃COO)₂Ca＋CO₂↑＋H₂O；(3) 漏斗；(4) 稀醋酸","method":"先写已知和所求，再列式计算，每一步写清依据，最后写结论。","answer":[],"explanation":"操作①把溶液和滤渣分开，是过滤。柠檬酸与醋酸钙复分解，生成柠檬酸钙和醋酸，物质 X 就是醋酸，可以回到第一步再用。","kp":"工艺流程","image":"./assets/national/jx-2026-chemistry/q17.webp","kpId":"chemistry-sp-p01","kpRef":true},{"id":"kp-chemistry-sp-p02-01","subject":"chemistry","subjectLabel":"化学","knowledge":true,"kpId":"chemistry-sp-p02","kp":"废液回收金属与矿石综合利用流程","unit":"专题·工业工艺流程压轴","chapter":"专题与压轴 · 工业工艺流程压轴","source":"知识点精练 · 专题与压轴 · 废液回收金属与矿石综合利用流程（基础）","level":1,"kpFree":true,"type":"single","stem":"从含有 CuSO4 和 FeSO4 的工业废液中回收纯铜和绿矾（FeSO4·7H2O），第一步应向废液中加入过量的（ ）","options":[{"key":"A","text":"锌粉"},{"key":"B","text":"铜粉"},{"key":"C","text":"铁粉"},{"key":"D","text":"氢氧化钠"}],"answer":["C"],"explanation":"加过量铁粉把 Cu²⁺ 全部置换为 Cu，同时生成目标产物 FeSO4，不引入新杂质。"},{"id":"kp-chemistry-sp-p02-02","subject":"chemistry","subjectLabel":"化学","knowledge":true,"kpId":"chemistry-sp-p02","kp":"废液回收金属与矿石综合利用流程","unit":"专题·工业工艺流程压轴","chapter":"专题与压轴 · 工业工艺流程压轴","source":"知识点精练 · 专题与压轴 · 废液回收金属与矿石综合利用流程（基础）","level":1,"kpFree":true,"type":"single","stem":"从含 CuSO4 和 FeSO4 的废液中加入过量铁粉充分反应后过滤，所得滤渣（含 Cu 和过量 Fe）应加入足量哪种试剂以得到纯净铜且滤液仍为 FeSO4（ ）","options":[{"key":"A","text":"硝酸银溶液"},{"key":"B","text":"水"},{"key":"C","text":"稀盐酸"},{"key":"D","text":"稀硫酸"}],"answer":["D"],"explanation":"稀硫酸与过量铁反应生成 FeSO4，既提纯了铜又回收了 FeSO4 溶液。"},{"id":"kp-chemistry-sp-p02-03","subject":"chemistry","subjectLabel":"化学","knowledge":true,"kpId":"chemistry-sp-p02","kp":"废液回收金属与矿石综合利用流程","unit":"专题·工业工艺流程压轴","chapter":"专题与压轴 · 工业工艺流程压轴","source":"知识点精练 · 专题与压轴 · 废液回收金属与矿石综合利用流程（基础）","level":1,"kpFree":true,"type":"blank","stem":"在湿法炼铜工艺中，向铁矿废渣加稀硫酸浸出时，常常采取“搅拌”和“适当加热”的措施，目的是加快______。","blanks":[["反应速率","浸出速率"]],"answer":["反应速率"],"explanation":"搅拌与升温均可加快固液反应速率。"},{"id":"kp-chemistry-sp-p02-04","subject":"chemistry","subjectLabel":"化学","knowledge":true,"kpId":"chemistry-sp-p02","kp":"废液回收金属与矿石综合利用流程","unit":"专题·工业工艺流程压轴","chapter":"专题与压轴 · 工业工艺流程压轴","source":"知识点精练 · 专题与压轴 · 废液回收金属与矿石综合利用流程（提高）","level":2,"kpFree":true,"kpDiag":true,"type":"single","stem":"某废旧电路板浸出液含 CuCl2、FeCl2，为回收金属铜并制取纯净 FeCl2 溶液，除过量铁粉时应选用的酸是（ ）","options":[{"key":"A","text":"稀盐酸"},{"key":"B","text":"稀硫酸"},{"key":"C","text":"稀硝酸"},{"key":"D","text":"碳酸"}],"answer":["A"],"explanation":"目标溶质是 FeCl2，故选用稀盐酸避免引入 SO4²⁻ 杂质。"},{"id":"kp-chemistry-sp-p02-05","subject":"chemistry","subjectLabel":"化学","knowledge":true,"kpId":"chemistry-sp-p02","kp":"废液回收金属与矿石综合利用流程","unit":"专题·工业工艺流程压轴","chapter":"专题与压轴 · 工业工艺流程压轴","source":"知识点精练 · 专题与压轴 · 废液回收金属与矿石综合利用流程（提高）","level":2,"kpFree":false,"type":"single","stem":"工业上用菱镁矿（主要含 MgCO3，杂质 SiO2 不溶于水也不溶于酸）制 MgSO4：先加过量稀硫酸酸浸再过滤，滤渣的主要成分是（ ）","options":[{"key":"A","text":"MgSO4"},{"key":"B","text":"SiO2"},{"key":"C","text":"MgCO3"},{"key":"D","text":"H2SO4"}],"answer":["B"],"explanation":"MgCO3 溶于稀硫酸生成可溶 MgSO4，不反应的 SiO2 留在滤渣中。"},{"id":"kp-chemistry-sp-p02-06","subject":"chemistry","subjectLabel":"化学","knowledge":true,"kpId":"chemistry-sp-p02","kp":"废液回收金属与矿石综合利用流程","unit":"专题·工业工艺流程压轴","chapter":"专题与压轴 · 工业工艺流程压轴","source":"知识点精练 · 专题与压轴 · 废液回收金属与矿石综合利用流程（提高）","level":2,"kpFree":false,"type":"blank","stem":"工业上用含 AgNO3、Cu(NO3)2、Zn(NO3)2 的废液回收 Ag 和 Cu，先加过量铁粉过滤，则滤液中一定含有的两种溶质是 Zn(NO3)2 和______（填化学式）。","blanks":[["Fe(NO3)2"]],"answer":["Fe(NO3)2"],"explanation":"铁不能置换 Zn，能置换 Ag 和 Cu 并生成 Fe(NO3)2。"},{"id":"kp-chemistry-sp-p02-07","subject":"chemistry","subjectLabel":"化学","knowledge":true,"kpId":"chemistry-sp-p02","kp":"废液回收金属与矿石综合利用流程","unit":"专题·工业工艺流程压轴","chapter":"专题与压轴 · 工业工艺流程压轴","source":"知识点精练 · 专题与压轴 · 废液回收金属与矿石综合利用流程（拓展）","level":3,"kpFree":false,"type":"single","stem":"从溶液中提取溶解度受温度变化影响较大的硫酸铜晶体，常用的结晶操作是（ ）","options":[{"key":"A","text":"加活性炭吸附"},{"key":"B","text":"直接过滤"},{"key":"C","text":"蒸发浓缩、降温结晶、过滤"},{"key":"D","text":"直接蒸干"}],"answer":["C"],"explanation":"蒸发浓缩、降温结晶可析出纯净大颗粒晶体且防止结晶水合物分解。"},{"id":"kp-chemistry-sp-p02-08","subject":"chemistry","subjectLabel":"化学","knowledge":true,"kpId":"chemistry-sp-p02","kp":"废液回收金属与矿石综合利用流程","unit":"专题·工业工艺流程压轴","chapter":"专题与压轴 · 工业工艺流程压轴","source":"知识点精练 · 专题与压轴 · 废液回收金属与矿石综合利用流程（拓展）","level":3,"kpFree":false,"type":"single","stem":"工业流程中常把滤渣用蒸馏水“洗涤 2～3 次”，其主要目的是（ ）","options":[{"key":"A","text":"使滤渣溶解"},{"key":"B","text":"降低温度"},{"key":"C","text":"增加滤渣质量"},{"key":"D","text":"洗去滤渣表面附着的可溶性杂质离子"}],"answer":["D"],"explanation":"洗涤除去滤渣表面残留的母液杂质，提高产品纯度。"},{"id":"kp-chemistry-sp-p02-09","subject":"chemistry","subjectLabel":"化学","knowledge":true,"kpId":"chemistry-sp-p02","kp":"废液回收金属与矿石综合利用流程","unit":"专题·工业工艺流程压轴","chapter":"专题与压轴 · 工业工艺流程压轴","source":"知识点精练 · 专题与压轴 · 废液回收金属与矿石综合利用流程（压轴解答）","level":3,"kpFree":false,"type":"essay","meta":"金属回收流程大题","stem":"某工厂废液中含有 CuSO₄、FeSO₄ 和少量 H₂SO₄，现回收金属铜并制得 FeSO₄ 晶体：向废液中加入过量铁粉，充分反应后过滤，得滤液 A 和滤渣 B；向滤渣 B 中加入适量稀硫酸，充分反应后过滤，得金属铜和滤液 C。（1）滤渣 B 的成分是什么？（2）写出向废液中加入过量铁粉时发生的两个化学方程式；（3）将滤液 A 和滤液 C 合并后，经什么操作可得到 FeSO₄ 晶体？","score":10,"points":[{"text":"（1）滤渣 B 含有 Cu 和过量的 Fe（铜和铁）","score":2,"keys":["Cu","Fe","铜","铁"]},{"text":"（2）Fe＋CuSO₄＝FeSO₄＋Cu；Fe＋H₂SO₄＝FeSO₄＋H₂↑","score":5,"keys":["FeSO₄＋Cu","FeSO4+Cu","H₂↑","H2"]},{"text":"（3）蒸发浓缩、降温结晶、过滤（或蒸发结晶）","score":3,"keys":["结晶","蒸发"]}],"method":"① 加过量铁粉目的：把废液中的 CuSO₄ 全部置换为 Cu，同时消耗掉 H₂SO₄，且只生成目标溶质 FeSO₄ 不引入新杂质；② 滤渣里一定含置换出的 Cu 和过量的 Fe，用稀硫酸溶解多余的 Fe（铜不与稀硫酸反应）；③ 合并后均为 FeSO₄ 溶液，蒸发浓缩、降温结晶即可。","sample":"解：（1）因为加入的铁粉是过量的，所以滤渣 B 的成分是：铜和铁（Cu、Fe）。\n（2）加入过量铁粉时发生的两个化学方程式：\n① Fe＋CuSO₄＝FeSO₄＋Cu；\n② Fe＋H₂SO₄＝FeSO₄＋H₂↑。\n（3）滤液 A 和滤液 C 均为 FeSO₄ 溶液，合并后经蒸发浓缩、降温结晶、过滤（洗涤、干燥）即可得到 FeSO₄ 晶体。","explanation":"阅卷提醒：第二问千万别漏写铁与废液中少量 H₂SO₄ 的反应，且气体符号 ↑ 必须标全！"},{"id":"kp-chemistry-sp-p03-01","subject":"chemistry","subjectLabel":"化学","knowledge":true,"kpId":"chemistry-sp-p03","kp":"碳捕集、双碳工艺与物质循环利用","unit":"专题·工业工艺流程压轴","chapter":"专题与压轴 · 工业工艺流程压轴","source":"知识点精练 · 专题与压轴 · 碳捕集、双碳工艺与物质循环利用（基础）","level":1,"kpFree":true,"image":"./assets/knowledge/chemistry/sp/p03-carbon.svg","type":"single","stem":"如图“碳捕捉”工艺流程中，可以循环利用的两种物质是（ ）","options":[{"key":"A","text":"NaOH 和 CaO"},{"key":"B","text":"只有 NaOH"},{"key":"C","text":"CaCO3 和 Na2CO3"},{"key":"D","text":"CO2 和 H2O"}],"answer":["A"],"explanation":"反应室再生 NaOH 回捕捉室，煅烧炉再生 CaO 回反应室，两者循环利用。"},{"id":"kp-chemistry-sp-p03-02","subject":"chemistry","subjectLabel":"化学","knowledge":true,"kpId":"chemistry-sp-p03","kp":"碳捕集、双碳工艺与物质循环利用","unit":"专题·工业工艺流程压轴","chapter":"专题与压轴 · 工业工艺流程压轴","source":"知识点精练 · 专题与压轴 · 碳捕集、双碳工艺与物质循环利用（基础）","level":1,"kpFree":true,"image":"./assets/knowledge/chemistry/sp/p03-carbon.svg","type":"single","stem":"如图碳捕捉室中，工业上常将 NaOH 溶液从塔顶以雾状“喷淋”而下，其主要目的是（ ）","options":[{"key":"A","text":"减少水蒸发"},{"key":"B","text":"增大气液接触面积，使 CO2 吸收更充分"},{"key":"C","text":"降低反应温度"},{"key":"D","text":"节约氢氧化钠"}],"answer":["B"],"explanation":"喷淋把液体分散成细小液滴，极大增大接触面积，提高吸收效率。"},{"id":"kp-chemistry-sp-p03-03","subject":"chemistry","subjectLabel":"化学","knowledge":true,"kpId":"chemistry-sp-p03","kp":"碳捕集、双碳工艺与物质循环利用","unit":"专题·工业工艺流程压轴","chapter":"专题与压轴 · 工业工艺流程压轴","source":"知识点精练 · 专题与压轴 · 碳捕集、双碳工艺与物质循环利用（基础）","level":1,"kpFree":true,"type":"blank","stem":"在碳捕捉工艺的高温煅烧炉中，发生反应的化学方程式为 CaCO3＝(高温)CaO＋______↑。","blanks":[["CO2"]],"answer":["CO2"],"explanation":"高温煅烧碳酸钙生成氧化钙和二氧化碳。"},{"id":"kp-chemistry-sp-p03-04","subject":"chemistry","subjectLabel":"化学","knowledge":true,"kpId":"chemistry-sp-p03","kp":"碳捕集、双碳工艺与物质循环利用","unit":"专题·工业工艺流程压轴","chapter":"专题与压轴 · 工业工艺流程压轴","source":"知识点精练 · 专题与压轴 · 碳捕集、双碳工艺与物质循环利用（提高）","level":2,"kpFree":true,"kpDiag":true,"type":"single","stem":"我国科学家实现二氧化碳催化加氢制甲醇：CO2＋3H2＝(催化剂)CH3OH＋X，则 X 的化学式为（ ）","options":[{"key":"A","text":"O2"},{"key":"B","text":"CO"},{"key":"C","text":"H2O"},{"key":"D","text":"CH4"}],"answer":["C"],"explanation":"根据原子守恒，左 1C、2O、6H，右已有 1C、1O、4H，故 X 为 H2O。"},{"id":"kp-chemistry-sp-p03-05","subject":"chemistry","subjectLabel":"化学","knowledge":true,"kpId":"chemistry-sp-p03","kp":"碳捕集、双碳工艺与物质循环利用","unit":"专题·工业工艺流程压轴","chapter":"专题与压轴 · 工业工艺流程压轴","source":"知识点精练 · 专题与压轴 · 碳捕集、双碳工艺与物质循环利用（提高）","level":2,"kpFree":false,"type":"single","stem":"碳捕捉工艺中，“反应室”内发生两个反应：CaO＋H2O＝Ca(OH)2 和 Ca(OH)2＋Na2CO3＝CaCO3↓＋2NaOH，将生成的 CaCO3 固体与 NaOH 溶液分离的操作是（ ）","options":[{"key":"A","text":"蒸发"},{"key":"B","text":"吸附"},{"key":"C","text":"蒸馏"},{"key":"D","text":"过滤"}],"answer":["D"],"explanation":"分离难溶固体和液体用过滤操作。"},{"id":"kp-chemistry-sp-p03-06","subject":"chemistry","subjectLabel":"化学","knowledge":true,"kpId":"chemistry-sp-p03","kp":"碳捕集、双碳工艺与物质循环利用","unit":"专题·工业工艺流程压轴","chapter":"专题与压轴 · 工业工艺流程压轴","source":"知识点精练 · 专题与压轴 · 碳捕集、双碳工艺与物质循环利用（提高）","level":2,"kpFree":false,"type":"single","stem":"下列做法不利于推进“碳中和”目标的是（ ）","options":[{"key":"A","text":"大力新建燃煤火电厂替代水电"},{"key":"B","text":"推广新能源汽车和公共交通"},{"key":"C","text":"研发 CO2 捕集与资源化利用技术"},{"key":"D","text":"发展绿氢和风电光伏发电"}],"answer":["A"],"explanation":"燃煤电厂排放大量 CO2，违背减碳方向。"},{"id":"kp-chemistry-sp-p03-07","subject":"chemistry","subjectLabel":"化学","knowledge":true,"kpId":"chemistry-sp-p03","kp":"碳捕集、双碳工艺与物质循环利用","unit":"专题·工业工艺流程压轴","chapter":"专题与压轴 · 工业工艺流程压轴","source":"知识点精练 · 专题与压轴 · 碳捕集、双碳工艺与物质循环利用（拓展）","level":3,"kpFree":false,"type":"blank","stem":"二氧化碳加氢制甲烷（CO2＋4H2＝CH4＋2H2O）中，若转化 44 t CO2，理论上需要消耗氢气______t（C-12, O-16, H-1）。","blanks":[["8"]],"answer":["8"],"explanation":"CO2∶4H2＝44∶8，故需 8 t 氢气。"},{"id":"kp-chemistry-sp-p03-08","subject":"chemistry","subjectLabel":"化学","knowledge":true,"kpId":"chemistry-sp-p03","kp":"碳捕集、双碳工艺与物质循环利用","unit":"专题·工业工艺流程压轴","chapter":"专题与压轴 · 工业工艺流程压轴","source":"知识点精练 · 专题与压轴 · 碳捕集、双碳工艺与物质循环利用（拓展）","level":3,"kpFree":false,"type":"single","stem":"评价“NaOH 碳捕捉”工艺，其实际推广中面临的最大缺点是（ ）","options":[{"key":"A","text":"不能吸收 CO2"},{"key":"B","text":"高温煅烧 CaCO3 耗能大、成本高"},{"key":"C","text":"产品无用"},{"key":"D","text":"NaOH 难溶于水"}],"answer":["B"],"explanation":"高温分解 CaCO3 需要消耗大量能源，能耗偏高。"},{"id":"kp-chemistry-sp-p04-01","subject":"chemistry","subjectLabel":"化学","knowledge":true,"kpId":"chemistry-sp-p04","kp":"题眼突破与初中常见“三角”转化框图推断","unit":"专题·框图推断与离子共存","chapter":"专题与压轴 · 框图推断与离子共存压轴","source":"知识点精练 · 专题与压轴 · 题眼突破与初中常见“三角”转化框图推断（基础）","level":1,"kpFree":true,"type":"single","stem":"初中化学常见物质 A、B 组成元素完全相同，常温下均为无色液体，且 A 在 MnO2 催化下可分解生成 B 和气体 C，则 A、B 分别是（ ）","options":[{"key":"A","text":"HCl 和 H2SO4"},{"key":"B","text":"O2 和 O3"},{"key":"C","text":"H2O2 和 H2O"},{"key":"D","text":"CO2 和 CO"}],"answer":["C"],"explanation":"常温无色液体且元素相同，H2O2 分解生成 H2O 和 O2。"},{"id":"kp-chemistry-sp-p04-02","subject":"chemistry","subjectLabel":"化学","knowledge":true,"kpId":"chemistry-sp-p04","kp":"题眼突破与初中常见“三角”转化框图推断","unit":"专题·框图推断与离子共存","chapter":"专题与压轴 · 框图推断与离子共存压轴","source":"知识点精练 · 专题与压轴 · 题眼突破与初中常见“三角”转化框图推断（基础）","level":1,"kpFree":true,"image":"./assets/knowledge/chemistry/sp/p04-infer.svg","type":"single","stem":"如图钙三角转化中，A 为大理石主要成分，B 为常用食品干燥剂，C 可改良酸性土壤，则 B 转化为 C 的反应类型是（ ）","options":[{"key":"A","text":"置换反应"},{"key":"B","text":"复分解反应"},{"key":"C","text":"分解反应"},{"key":"D","text":"化合反应"}],"answer":["D"],"explanation":"CaO＋H2O＝Ca(OH)2，符合“多变一”化合反应。"},{"id":"kp-chemistry-sp-p04-03","subject":"chemistry","subjectLabel":"化学","knowledge":true,"kpId":"chemistry-sp-p04","kp":"题眼突破与初中常见“三角”转化框图推断","unit":"专题·框图推断与离子共存","chapter":"专题与压轴 · 框图推断与离子共存压轴","source":"知识点精练 · 专题与压轴 · 题眼突破与初中常见“三角”转化框图推断（基础）","level":1,"kpFree":true,"type":"blank","stem":"某红棕色固体粉末 A 在高温下与有毒气体 B 反应，生成黑色金属单质 C 和能使澄清石灰水变浑浊的气体 D，则红棕色粉末 A 的化学式为______。","blanks":[["Fe2O3"]],"answer":["Fe2O3"],"explanation":"3CO＋Fe2O3＝(高温)2Fe＋3CO2，红棕色固体为 Fe2O3。"},{"id":"kp-chemistry-sp-p04-04","subject":"chemistry","subjectLabel":"化学","knowledge":true,"kpId":"chemistry-sp-p04","kp":"题眼突破与初中常见“三角”转化框图推断","unit":"专题·框图推断与离子共存","chapter":"专题与压轴 · 框图推断与离子共存压轴","source":"知识点精练 · 专题与压轴 · 题眼突破与初中常见“三角”转化框图推断（提高）","level":2,"kpFree":true,"kpDiag":true,"type":"single","stem":"黑色固体甲与黑色固体乙在高温下反应，生成红色金属单质丙和能灭火的气体丁，则甲、乙分别是（ ）","options":[{"key":"A","text":"C 和 CuO"},{"key":"B","text":"Fe3O4 和 MnO2"},{"key":"C","text":"Fe 和 CuO"},{"key":"D","text":"C 和 Fe2O3"}],"answer":["A"],"explanation":"C 和 CuO 均为黑色固体，高温生成红色 Cu 和 CO2（灭火）。"},{"id":"kp-chemistry-sp-p04-05","subject":"chemistry","subjectLabel":"化学","knowledge":true,"kpId":"chemistry-sp-p04","kp":"题眼突破与初中常见“三角”转化框图推断","unit":"专题·框图推断与离子共存","chapter":"专题与压轴 · 框图推断与离子共存压轴","source":"知识点精练 · 专题与压轴 · 题眼突破与初中常见“三角”转化框图推断（提高）","level":2,"kpFree":false,"type":"blank","stem":"A、B 为组成元素相同的无色气体，A 有剧毒且可用于冶炼金属，B 可用于光合作用，则 A 转化为 B 可通过燃烧，B 转化为 A 需与______（填化学式）在高温下反应。","blanks":[["C"]],"answer":["C"],"explanation":"CO2＋C＝(高温)2CO。"},{"id":"kp-chemistry-sp-p04-06","subject":"chemistry","subjectLabel":"化学","knowledge":true,"kpId":"chemistry-sp-p04","kp":"题眼突破与初中常见“三角”转化框图推断","unit":"专题·框图推断与离子共存","chapter":"专题与压轴 · 框图推断与离子共存压轴","source":"知识点精练 · 专题与压轴 · 题眼突破与初中常见“三角”转化框图推断（提高）","level":2,"kpFree":false,"type":"single","stem":"某蓝色溶液 X 与无色溶液 Y 反应生成蓝色沉淀和硫酸钠，则 X 和 Y 最可能是（ ）","options":[{"key":"A","text":"CuCl2 和 NaOH"},{"key":"B","text":"CuSO4 和 NaOH"},{"key":"C","text":"FeCl3 和 NaOH"},{"key":"D","text":"CuSO4 和 BaCl2"}],"answer":["B"],"explanation":"CuSO4＋2NaOH＝Cu(OH)2↓＋Na2SO4。"},{"id":"kp-chemistry-sp-p04-07","subject":"chemistry","subjectLabel":"化学","knowledge":true,"kpId":"chemistry-sp-p04","kp":"题眼突破与初中常见“三角”转化框图推断","unit":"专题·框图推断与离子共存","chapter":"专题与压轴 · 框图推断与离子共存压轴","source":"知识点精练 · 专题与压轴 · 题眼突破与初中常见“三角”转化框图推断（拓展）","level":3,"kpFree":false,"type":"blank","stem":"某白色固体甲受热分解生成三种物质，其中一种是黑色固体乙（可作双氧水分解催化剂），一种是能使带火星木条复燃的气体丙，则白色或暗紫色固体甲应为高锰酸钾，黑色固体乙化学式为______。","blanks":[["MnO2"]],"answer":["MnO2"],"explanation":"2KMnO4＝(△)K2MnO4＋MnO2＋O2↑，催化剂乙是 MnO2。"},{"id":"kp-chemistry-sp-p04-08","subject":"chemistry","subjectLabel":"化学","knowledge":true,"kpId":"chemistry-sp-p04","kp":"题眼突破与初中常见“三角”转化框图推断","unit":"专题·框图推断与离子共存","chapter":"专题与压轴 · 框图推断与离子共存压轴","source":"知识点精练 · 专题与压轴 · 题眼突破与初中常见“三角”转化框图推断（拓展）","level":3,"kpFree":false,"type":"single","stem":"已知 A→B→C→A 为循环转化：A 是人体胃液中的酸，B 是蓝色溶液，C 是浅绿色溶液，下列推断合理的是（ ）","options":[{"key":"A","text":"A 为 HCl，B 为 FeCl3，C 为 CuCl2"},{"key":"B","text":"A 为 H2SO4，B 为 FeCl3，C 为 CuSO4"},{"key":"C","text":"A 为 HCl，B 为 CuCl2，C 为 FeCl2"},{"key":"D","text":"A 为 NaOH，B 为 CuSO4，C 为 FeSO4"}],"answer":["C"],"explanation":"HCl＋CuO→CuCl2(蓝)；CuCl2＋Fe→FeCl2(浅绿)。"},{"id":"kp-chemistry-sp-p04-09","subject":"chemistry","subjectLabel":"化学","knowledge":true,"kpId":"chemistry-sp-p04","kp":"题眼突破与初中常见“三角”转化框图推断","unit":"专题·框图推断与离子共存","chapter":"专题与压轴 · 框图推断与离子共存压轴","source":"知识点精练 · 专题与压轴 · 题眼突破与初中常见“三角”转化框图推断（压轴解答）","level":3,"kpFree":false,"type":"essay","meta":"框图推断压轴大题","stem":"A、B、C、D、E 是初中化学常见物质。已知 A 是大理石的主要成分，B、D 组成元素相同且均为无色气体，C 是黑色固体单质，E 俗称熟石灰。它们存在如下转化：A 高温分解生成 B 和一种氧化物；B 与 C 在高温下反应生成 D；B 与 E 反应生成 A 和水。（1）写出 A、B、C、D 的化学式；（2）写出 B 与 C 反应的化学方程式；（3）写出 B 与 E 反应的化学方程式，并说出该反应在实验室的常见用途。","score":10,"points":[{"text":"（1）A：CaCO₃，B：CO₂，C：C，D：CO","score":4,"keys":["CaCO₃","CaCO3","CO₂","CO2","CO"]},{"text":"（2）CO₂＋C ＝高温＝ 2CO","score":3,"keys":["高温","2CO"]},{"text":"（3）CO₂＋Ca(OH)₂＝CaCO₃↓＋H₂O；用途：检验二氧化碳气体","score":3,"keys":["Ca(OH)₂","Ca(OH)2","CaCO₃↓","检验"]}],"method":"① 抓四大“题眼”：大理石主要成分＝CaCO₃，组成元素相同的无色气体＝CO₂/CO，黑色固体单质＝C，熟石灰＝Ca(OH)₂；② 顺藤摸瓜代入所有转化逐一验通；③ 注意反应条件（高温）和沉淀符号（↓）。","sample":"解：（1）各物质化学式：A 为 CaCO₃，B 为 CO₂，C 为 C，D 为 CO。\n（2）B 与 C 在高温下反应的化学方程式：\nCO₂＋C ＝高温＝ 2CO（该反应为吸热反应）。\n（3）B 与 E 反应的化学方程式：\nCO₂＋Ca(OH)₂＝CaCO₃↓＋H₂O。\n在实验室中常利用该反应（澄清石灰水变浑浊）来检验二氧化碳气体。","explanation":"推断题防扣分三件事：看清问的是“名称”还是“化学式”、高温条件别漏写、CaCO₃ 沉淀符号 ↓ 别漏标。"},{"id":"kp-chemistry-sp-p05-01","subject":"chemistry","subjectLabel":"化学","knowledge":true,"kpId":"chemistry-sp-p05","kp":"酸碱盐隐含条件（无色/pH/气体沉淀）离子共存压轴","unit":"专题·框图推断与离子共存","chapter":"专题与压轴 · 框图推断与离子共存压轴","source":"知识点精练 · 专题与压轴 · 酸碱盐隐含条件（无色/pH/气体沉淀）离子共存压轴（基础）","level":1,"kpFree":true,"type":"single","stem":"在 pH＝13 的强碱性溶液中，下列各组离子能大量共存的是（ ）","options":[{"key":"A","text":"H⁺、Na⁺、NO3⁻"},{"key":"B","text":"NH4⁺、K⁺、Cl⁻"},{"key":"C","text":"Cu²⁺、Na⁺、SO4²⁻"},{"key":"D","text":"K⁺、Na⁺、NO3⁻、CO3²⁻"}],"answer":["D"],"explanation":"pH＝13 含大量 OH⁻，与 H⁺、NH4⁺、Cu²⁺ 均不能共存，只有 C 能共存。"},{"id":"kp-chemistry-sp-p05-02","subject":"chemistry","subjectLabel":"化学","knowledge":true,"kpId":"chemistry-sp-p05","kp":"酸碱盐隐含条件（无色/pH/气体沉淀）离子共存压轴","unit":"专题·框图推断与离子共存","chapter":"专题与压轴 · 框图推断与离子共存压轴","source":"知识点精练 · 专题与压轴 · 酸碱盐隐含条件（无色/pH/气体沉淀）离子共存压轴（基础）","level":1,"kpFree":true,"type":"single","stem":"在无色透明的溶液中，下列各组离子能大量共存的是（ ）","options":[{"key":"A","text":"Na⁺、K⁺、Cl⁻、NO3⁻"},{"key":"B","text":"Fe³⁺、K⁺、NO3⁻、Cl⁻"},{"key":"C","text":"Cu²⁺、Na⁺、SO4²⁻、Cl⁻"},{"key":"D","text":"Ba²⁺、Na⁺、SO4²⁻、NO3⁻"}],"answer":["A"],"explanation":"A 蓝色，B 黄色，D 生成 BaSO4 沉淀，只有 C 无色且互不反应。"},{"id":"kp-chemistry-sp-p05-03","subject":"chemistry","subjectLabel":"化学","knowledge":true,"kpId":"chemistry-sp-p05","kp":"酸碱盐隐含条件（无色/pH/气体沉淀）离子共存压轴","unit":"专题·框图推断与离子共存","chapter":"专题与压轴 · 框图推断与离子共存压轴","source":"知识点精练 · 专题与压轴 · 酸碱盐隐含条件（无色/pH/气体沉淀）离子共存压轴（基础）","level":1,"kpFree":true,"type":"single","stem":"向某溶液中加入紫色石蕊试液显红色，则该溶液中一定不能大量存在的离子是（ ）","options":[{"key":"A","text":"SO4²⁻"},{"key":"B","text":"CO3²⁻"},{"key":"C","text":"Cl⁻"},{"key":"D","text":"Na⁺"}],"answer":["B"],"explanation":"石蕊变红说明含大量 H⁺，H⁺ 与 CO3²⁻ 反应生成 CO2 和 H2O 不能共存。"},{"id":"kp-chemistry-sp-p05-04","subject":"chemistry","subjectLabel":"化学","knowledge":true,"kpId":"chemistry-sp-p05","kp":"酸碱盐隐含条件（无色/pH/气体沉淀）离子共存压轴","unit":"专题·框图推断与离子共存","chapter":"专题与压轴 · 框图推断与离子共存压轴","source":"知识点精练 · 专题与压轴 · 酸碱盐隐含条件（无色/pH/气体沉淀）离子共存压轴（提高）","level":2,"kpFree":true,"kpDiag":true,"type":"single","stem":"某工厂废水中含有大量 Ba²⁺、Cl⁻、NO3⁻，现需加入一种物质使 Ba²⁺ 沉淀，且不能引入难以共存的 Ag⁺，应选用的离子是（ ）","options":[{"key":"A","text":"Na⁺"},{"key":"B","text":"K⁺"},{"key":"C","text":"SO4²⁻（如 Na2SO4）"},{"key":"D","text":"H⁺"}],"answer":["C"],"explanation":"Ba²⁺ 与 SO4²⁻ 生成难溶 BaSO4 沉淀。"},{"id":"kp-chemistry-sp-p05-05","subject":"chemistry","subjectLabel":"化学","knowledge":true,"kpId":"chemistry-sp-p05","kp":"酸碱盐隐含条件（无色/pH/气体沉淀）离子共存压轴","unit":"专题·框图推断与离子共存","chapter":"专题与压轴 · 框图推断与离子共存压轴","source":"知识点精练 · 专题与压轴 · 酸碱盐隐含条件（无色/pH/气体沉淀）离子共存压轴（提高）","level":2,"kpFree":false,"type":"single","stem":"将甲、乙两种各含两种不同离子的澄清溶液混合，若甲含 Ag⁺、NO3⁻，则乙中一定不可能含有的离子是（ ）","options":[{"key":"A","text":"Mg²⁺"},{"key":"B","text":"K⁺"},{"key":"C","text":"Na⁺"},{"key":"D","text":"Cl⁻"}],"answer":["D"],"explanation":"Ag⁺ 与 Cl⁻ 结合生成白色 AgCl 沉淀。"},{"id":"kp-chemistry-sp-p05-06","subject":"chemistry","subjectLabel":"化学","knowledge":true,"kpId":"chemistry-sp-p05","kp":"酸碱盐隐含条件（无色/pH/气体沉淀）离子共存压轴","unit":"专题·框图推断与离子共存","chapter":"专题与压轴 · 框图推断与离子共存压轴","source":"知识点精练 · 专题与压轴 · 酸碱盐隐含条件（无色/pH/气体沉淀）离子共存压轴（提高）","level":2,"kpFree":false,"type":"single","stem":"在含有大量 H⁺、Na⁺、Cl⁻ 的溶液中，还可以大量共存的离子是（ ）","options":[{"key":"A","text":"Mg²⁺"},{"key":"B","text":"OH⁻"},{"key":"C","text":"HCO3⁻"},{"key":"D","text":"Ag⁺"}],"answer":["A"],"explanation":"H⁺ 排斥 OH⁻ 和 HCO3⁻，Cl⁻ 排斥 Ag⁺，只有 Mg²⁺ 可以共存。"},{"id":"kp-chemistry-sp-p05-07","subject":"chemistry","subjectLabel":"化学","knowledge":true,"kpId":"chemistry-sp-p05","kp":"酸碱盐隐含条件（无色/pH/气体沉淀）离子共存压轴","unit":"专题·框图推断与离子共存","chapter":"专题与压轴 · 框图推断与离子共存压轴","source":"知识点精练 · 专题与压轴 · 酸碱盐隐含条件（无色/pH/气体沉淀）离子共存压轴（拓展）","level":3,"kpFree":false,"type":"blank","stem":"某无色溶液可能含 Na⁺、Cu²⁺、Ba²⁺、SO4²⁻、CO3²⁻ 中的几种，先由“无色”直接排除______（填离子符号）。","blanks":[["Cu²⁺","Cu2+","Cu^2⁺"]],"answer":["Cu²⁺"],"explanation":"Cu²⁺ 在水溶液中呈蓝色，无色溶液必不含 Cu²⁺。"},{"id":"kp-chemistry-sp-p05-08","subject":"chemistry","subjectLabel":"化学","knowledge":true,"kpId":"chemistry-sp-p05","kp":"酸碱盐隐含条件（无色/pH/气体沉淀）离子共存压轴","unit":"专题·框图推断与离子共存","chapter":"专题与压轴 · 框图推断与离子共存压轴","source":"知识点精练 · 专题与压轴 · 酸碱盐隐含条件（无色/pH/气体沉淀）离子共存压轴（拓展）","level":3,"kpFree":false,"type":"single","stem":"向某待测液中先加足量稀硝酸无气泡，再滴加硝酸钡溶液产生白色沉淀，说明原溶液中一定含有（ ）","options":[{"key":"A","text":"OH⁻"},{"key":"B","text":"SO4²⁻"},{"key":"C","text":"Cl⁻"},{"key":"D","text":"CO3²⁻"}],"answer":["B"],"explanation":"加稀硝酸排除了 CO3²⁻ 干扰，再加 Ba(NO3)2 产生不溶于稀硝酸的白色沉淀必为 BaSO4，证明含 SO4²⁻。"},{"id":"kp-chemistry-sp-p06-01","subject":"chemistry","subjectLabel":"化学","knowledge":true,"kpId":"chemistry-sp-p06","kp":"金属与混合盐溶液滤渣滤液成分压轴","unit":"专题·框图推断与离子共存","chapter":"专题与压轴 · 框图推断与离子共存压轴","source":"知识点精练 · 专题与压轴 · 金属与混合盐溶液滤渣滤液成分压轴（基础）","level":1,"kpFree":true,"type":"single","stem":"向 AgNO3 和 Cu(NO3)2 的混合溶液中加入一定量锌粉，充分反应后过滤，滤渣中一定含有的金属是（ ）","options":[{"key":"A","text":"Zn"},{"key":"B","text":"Cu"},{"key":"C","text":"Ag"},{"key":"D","text":"Ag 和 Cu"}],"answer":["C"],"explanation":"Zn 最先置换出最不活泼的 Ag，无论锌量多少，滤渣必含 Ag。"},{"id":"kp-chemistry-sp-p06-02","subject":"chemistry","subjectLabel":"化学","knowledge":true,"kpId":"chemistry-sp-p06","kp":"金属与混合盐溶液滤渣滤液成分压轴","unit":"专题·框图推断与离子共存","chapter":"专题与压轴 · 框图推断与离子共存压轴","source":"知识点精练 · 专题与压轴 · 金属与混合盐溶液滤渣滤液成分压轴（基础）","level":1,"kpFree":true,"type":"single","stem":"向 AgNO3 和 Cu(NO3)2 混合溶液中加入一定量铁粉，过滤后向滤液中滴加稀盐酸产生白色沉淀，则滤渣的成分是（ ）","options":[{"key":"A","text":"只有 Cu"},{"key":"B","text":"Ag 和 Cu"},{"key":"C","text":"Ag、Cu 和 Fe"},{"key":"D","text":"只有 Ag"}],"answer":["D"],"explanation":"加盐酸产生 AgCl 白沉淀说明 AgNO3 还有剩余，故 Cu(NO3)2 尚未反应，滤渣只有 Ag。"},{"id":"kp-chemistry-sp-p06-03","subject":"chemistry","subjectLabel":"化学","knowledge":true,"kpId":"chemistry-sp-p06","kp":"金属与混合盐溶液滤渣滤液成分压轴","unit":"专题·框图推断与离子共存","chapter":"专题与压轴 · 框图推断与离子共存压轴","source":"知识点精练 · 专题与压轴 · 金属与混合盐溶液滤渣滤液成分压轴（基础）","level":1,"kpFree":true,"type":"single","stem":"向 AgNO3 和 Cu(NO3)2 混合液加铁粉过滤，若滤液呈蓝色，则滤渣中一定不含有的金属是（ ）","options":[{"key":"A","text":"Fe"},{"key":"B","text":"Cu"},{"key":"C","text":"Ag"},{"key":"D","text":"无法判断"}],"answer":["A"],"explanation":"滤液呈蓝色说明含 Cu²⁺，只要溶液还有 Cu²⁺ 就不可能剩余铁粉（Fe 会继续与 Cu²⁺ 反应）。"},{"id":"kp-chemistry-sp-p06-04","subject":"chemistry","subjectLabel":"化学","knowledge":true,"kpId":"chemistry-sp-p06","kp":"金属与混合盐溶液滤渣滤液成分压轴","unit":"专题·框图推断与离子共存","chapter":"专题与压轴 · 框图推断与离子共存压轴","source":"知识点精练 · 专题与压轴 · 金属与混合盐溶液滤渣滤液成分压轴（提高）","level":2,"kpFree":true,"kpDiag":true,"type":"single","stem":"向 AgNO3、Cu(NO3)2 和 Mg(NO3)2 的混合溶液中加入过量铁粉，充分反应后过滤，滤液中含有的溶质是（ ）","options":[{"key":"A","text":"只有 Fe(NO3)2"},{"key":"B","text":"Fe(NO3)2 和 Mg(NO3)2"},{"key":"C","text":"Cu(NO3)2 和 Mg(NO3)2"},{"key":"D","text":"Mg(NO3)2"}],"answer":["B"],"explanation":"Fe 比 Mg 弱不能置换 Mg(NO3)2，过量铁把 Ag⁺、Cu²⁺ 全换完，故滤液含 Fe(NO3)2 和 Mg(NO3)2。"},{"id":"kp-chemistry-sp-p06-05","subject":"chemistry","subjectLabel":"化学","knowledge":true,"kpId":"chemistry-sp-p06","kp":"金属与混合盐溶液滤渣滤液成分压轴","unit":"专题·框图推断与离子共存","chapter":"专题与压轴 · 框图推断与离子共存压轴","source":"知识点精练 · 专题与压轴 · 金属与混合盐溶液滤渣滤液成分压轴（提高）","level":2,"kpFree":false,"type":"blank","stem":"将一定量锌粉投入 Cu(NO3)2 和 AgNO3 混合液中，充分反应后过滤，若测得滤渣质量小于加入锌粉的质量，该情况______（填“可能”或“不可能”）发生。","blanks":[["可能"]],"answer":["可能"],"explanation":"Zn(65)换Cu(64)固体质量减轻，Zn(65)换2Ag(216)固体增重；若换出的 Cu 足够多而 Ag 很少，总质量可减轻。"},{"id":"kp-chemistry-sp-p06-06","subject":"chemistry","subjectLabel":"化学","knowledge":true,"kpId":"chemistry-sp-p06","kp":"金属与混合盐溶液滤渣滤液成分压轴","unit":"专题·框图推断与离子共存","chapter":"专题与压轴 · 框图推断与离子共存压轴","source":"知识点精练 · 专题与压轴 · 金属与混合盐溶液滤渣滤液成分压轴（提高）","level":2,"kpFree":false,"type":"single","stem":"向含 Cu(NO3)2 和 AgNO3 的混合液中加入一定量铁粉，充分反应后发现溶液质量比反应前减轻了，这是因为主要发生了（ ）","options":[{"key":"A","text":"蒸发水分"},{"key":"B","text":"Fe＋Cu(NO3)2＝Fe(NO3)2＋Cu"},{"key":"C","text":"Fe＋2AgNO3＝Fe(NO3)2＋2Ag（56 份铁换 216 份银，溶液变轻）"},{"key":"D","text":"铁与水反应"}],"answer":["C"],"explanation":"每 56 份 Fe 进溶液换出 216 份 Ag，溶液质量显著减轻。"},{"id":"kp-chemistry-sp-p06-07","subject":"chemistry","subjectLabel":"化学","knowledge":true,"kpId":"chemistry-sp-p06","kp":"金属与混合盐溶液滤渣滤液成分压轴","unit":"专题·框图推断与离子共存","chapter":"专题与压轴 · 框图推断与离子共存压轴","source":"知识点精练 · 专题与压轴 · 金属与混合盐溶液滤渣滤液成分压轴（拓展）","level":3,"kpFree":false,"type":"single","stem":"向 Cu(NO3)2、AgNO3 混合液中加入一定量铁粉，过滤后向滤渣滴加稀盐酸有气泡产生，则滤液中含有的金属阳离子只有（ ）","options":[{"key":"A","text":"Ag⁺"},{"key":"B","text":"Cu²⁺"},{"key":"C","text":"Fe³⁺"},{"key":"D","text":"Fe²⁺"}],"answer":["D"],"explanation":"滤渣加盐酸有气泡说明铁粉过量，Ag⁺ 和 Cu²⁺ 均被彻底置换，滤液只剩 Fe²⁺。"},{"id":"kp-chemistry-sp-p06-08","subject":"chemistry","subjectLabel":"化学","knowledge":true,"kpId":"chemistry-sp-p06","kp":"金属与混合盐溶液滤渣滤液成分压轴","unit":"专题·框图推断与离子共存","chapter":"专题与压轴 · 框图推断与离子共存压轴","source":"知识点精练 · 专题与压轴 · 金属与混合盐溶液滤渣滤液成分压轴（拓展）","level":3,"kpFree":false,"type":"single","stem":"将铁粉和铜粉的混合物投入足量 AgNO3 溶液中，充分反应后过滤，滤渣中含有的金属是（ ）","options":[{"key":"A","text":"只有 Ag"},{"key":"B","text":"只有 Cu"},{"key":"C","text":"Ag、Cu 和 Fe"},{"key":"D","text":"Ag 和 Cu"}],"answer":["A"],"explanation":"AgNO3 足量，Fe 和 Cu 均排在 Ag 前面，会全部反应完，滤渣只有 Ag。"},{"id":"kp-chemistry-sp-p06-09","subject":"chemistry","subjectLabel":"化学","knowledge":true,"kpId":"chemistry-sp-p06","kp":"金属与混合盐溶液滤渣滤液成分压轴","unit":"专题·框图推断与离子共存","chapter":"专题与压轴 · 框图推断与离子共存压轴","source":"知识点精练 · 专题与压轴 · 金属与混合盐溶液滤渣滤液成分压轴（压轴解答）","level":3,"kpFree":false,"type":"essay","meta":"金属滤渣滤液压轴","stem":"向含有 AgNO₃ 和 Cu(NO₃)₂ 的混合溶液中加入一定量铁粉，充分反应后过滤，得到滤渣和滤液。（1）写出最先发生的化学方程式；（2）若向滤渣中滴加稀盐酸有气泡产生，请判断滤渣的成分和滤液中的溶质；（3）若观察到滤液呈蓝色，判断滤渣中一定有什么、可能有什么？","score":10,"points":[{"text":"（1）最先发生：Fe＋2AgNO₃＝Fe(NO₃)₂＋2Ag","score":3,"keys":["2AgNO₃","2AgNO3","Fe(NO₃)₂","2Ag"]},{"text":"（2）有气泡说明铁过量：滤渣含 Ag、Cu、Fe；滤液溶质只有 Fe(NO₃)₂","score":4,"keys":["Ag","Cu","Fe","Fe(NO₃)₂","Fe(NO3)2"]},{"text":"（3）滤液呈蓝色说明含 Cu(NO₃)₂：滤渣中一定有 Ag，可能有 Cu（一定没有 Fe）","score":3,"keys":["一定有Ag","一定有 Ag","可能有Cu","可能有 Cu"]}],"method":"① 遵循“远距离先置换”原则：活动性 Fe＞Cu＞Ag，Fe 先与 AgNO₃ 反应，AgNO₃ 耗尽后再与 Cu(NO₃)₂ 反应；② 滤渣加盐酸有气泡→必含过量 Fe→两种盐都被完全置换；③ 滤液呈蓝色→含 Cu(NO₃)₂→Fe 一定完全耗尽，Cu 可能部分置换出也可能尚未置换。","sample":"解：（1）在金属活动性顺序中 Fe＞Cu＞Ag，铁先与活动性最弱的银的盐溶液反应：\nFe＋2AgNO₃＝Fe(NO₃)₂＋2Ag。\n（2）向滤渣中滴加稀盐酸有气泡产生，说明滤渣中含有过量的铁粉，原溶液中的 AgNO₃ 和 Cu(NO₃)₂ 均已完全反应。\n因此，滤渣成分为 Ag、Cu、Fe；滤液中的溶质只有 Fe(NO₃)₂。\n（3）滤液呈蓝色，说明滤液中含有 Cu(NO₃)₂，则铁粉一定已完全反应。\n由于铁先置换出银，再置换铜（可能刚好耗尽在第一步，也可能部分置换了铜），\n故滤渣中一定有 Ag，可能有 Cu，一定没有 Fe。","explanation":"经典易错点：铁与盐溶液发生置换反应生成的都是亚铁盐 Fe(NO₃)₂，千万不能写成 Fe(NO₃)₃！"},{"id":"national-js-suzhou-2026-chemistry-q19","national":true,"subject":"chemistry","subjectLabel":"化学","paperId":"js-suzhou-2026-chemistry","number":19,"section":"单项选择","chapter":"2026 年苏州中考化学","grade":"九下","stage":"9-down","source":"2026 年苏州中考化学 第 19 题","type":"single","options":[{"key":"A","text":"CaO →(H₂O) Ca(OH)₂"},{"key":"B","text":"Fe₂O₃ →(稀盐酸) FeCl₃"},{"key":"C","text":"Ag →(MgSO₄ 溶液) Mg"},{"key":"D","text":"Zn →(稀硫酸) ZnSO₄"}],"answer":["C"],"explanation":"银的活动性比镁弱，不能把镁从它的盐溶液中置换出来。","kp":"金属活动性顺序","stem":"在给定条件下，下列选项所示的物质转化【不能】实现的是（ ）","paperScore":2,"kpId":"chemistry-sp-p06","kpRef":true},{"id":"kp-chemistry-sp-p07-01","subject":"chemistry","subjectLabel":"化学","knowledge":true,"kpId":"chemistry-sp-p07","kp":"氢氧化钠与生石灰变质程度探究（未变/部分/完全）","unit":"专题·实验探究与除杂鉴别","chapter":"专题与压轴 · 实验探究（变质/成分/除杂鉴别）压轴","source":"知识点精练 · 专题与压轴 · 氢氧化钠与生石灰变质程度探究（未变/部分/完全）（基础）","level":1,"kpFree":true,"type":"single","stem":"检验一瓶久置的氢氧化钠溶液是否已经变质，下列试剂中不能使用的是（ ）","options":[{"key":"A","text":"过量稀盐酸"},{"key":"B","text":"无色酚酞溶液"},{"key":"C","text":"澄清石灰水"},{"key":"D","text":"氯化钙溶液"}],"answer":["B"],"explanation":"NaOH 和变质生成的 Na2CO3 溶液都呈碱性，都能使酚酞变红，故酚酞无法判断是否变质。"},{"id":"kp-chemistry-sp-p07-02","subject":"chemistry","subjectLabel":"化学","knowledge":true,"kpId":"chemistry-sp-p07","kp":"氢氧化钠与生石灰变质程度探究（未变/部分/完全）","unit":"专题·实验探究与除杂鉴别","chapter":"专题与压轴 · 实验探究（变质/成分/除杂鉴别）压轴","source":"知识点精练 · 专题与压轴 · 氢氧化钠与生石灰变质程度探究（未变/部分/完全）（基础）","level":1,"kpFree":true,"image":"./assets/knowledge/chemistry/sp/p07-naoh.svg","type":"single","stem":"如图探究久置 NaOH 溶液是“部分变质”还是“完全变质”时，第一步加入过量 CaCl2 溶液后产生白色沉淀，静置取上层清液滴加酚酞溶液变红，说明该 NaOH 溶液（ ）","options":[{"key":"A","text":"无法判断"},{"key":"B","text":"完全变质"},{"key":"C","text":"部分变质"},{"key":"D","text":"没有变质"}],"answer":["C"],"explanation":"白沉淀说明含 Na2CO3（已变质），除尽 Na2CO3 后清液仍使酚酞变红说明还含 NaOH，故为部分变质。"},{"id":"kp-chemistry-sp-p07-03","subject":"chemistry","subjectLabel":"化学","knowledge":true,"kpId":"chemistry-sp-p07","kp":"氢氧化钠与生石灰变质程度探究（未变/部分/完全）","unit":"专题·实验探究与除杂鉴别","chapter":"专题与压轴 · 实验探究（变质/成分/除杂鉴别）压轴","source":"知识点精练 · 专题与压轴 · 氢氧化钠与生石灰变质程度探究（未变/部分/完全）（基础）","level":1,"kpFree":true,"image":"./assets/knowledge/chemistry/sp/p07-naoh.svg","type":"single","stem":"如图实验第一步中，不能用过量 Ca(OH)2 溶液代替过量 CaCl2 溶液的原因是（ ）","options":[{"key":"A","text":"Ca(OH)2 价格太贵"},{"key":"B","text":"会产生气体"},{"key":"C","text":"Ca(OH)2 不与 Na2CO3 反应"},{"key":"D","text":"Ca(OH)2 与 Na2CO3 反应会生成新的 NaOH（且自身显碱性），干扰原 NaOH 的检验"}],"answer":["D"],"explanation":"生成新 NaOH 且过量 Ca(OH)2 也会使酚酞变红，无法确定原样品是否含 NaOH。"},{"id":"kp-chemistry-sp-p07-04","subject":"chemistry","subjectLabel":"化学","knowledge":true,"kpId":"chemistry-sp-p07","kp":"氢氧化钠与生石灰变质程度探究（未变/部分/完全）","unit":"专题·实验探究与除杂鉴别","chapter":"专题与压轴 · 实验探究（变质/成分/除杂鉴别）压轴","source":"知识点精练 · 专题与压轴 · 氢氧化钠与生石灰变质程度探究（未变/部分/完全）（提高）","level":2,"kpFree":true,"kpDiag":true,"type":"single","stem":"若要除去 NaOH 溶液中混有的少量 Na2CO3 杂质以提纯 NaOH，应选用的试剂是（ ）","options":[{"key":"A","text":"适量氢氧化钙溶液，再过滤"},{"key":"B","text":"二氧化碳"},{"key":"C","text":"适量稀盐酸"},{"key":"D","text":"适量氯化钙溶液"}],"answer":["A"],"explanation":"Na2CO3＋Ca(OH)2＝CaCO3↓＋2NaOH，过滤即可得纯净 NaOH 溶液；用 CaCl2 会引入 NaCl 杂质。"},{"id":"kp-chemistry-sp-p07-05","subject":"chemistry","subjectLabel":"化学","knowledge":true,"kpId":"chemistry-sp-p07","kp":"氢氧化钠与生石灰变质程度探究（未变/部分/完全）","unit":"专题·实验探究与除杂鉴别","chapter":"专题与压轴 · 实验探究（变质/成分/除杂鉴别）压轴","source":"知识点精练 · 专题与压轴 · 氢氧化钠与生石灰变质程度探究（未变/部分/完全）（提高）","level":2,"kpFree":false,"type":"blank","stem":"检验 NaOH 溶液是否变质时，若滴加的稀盐酸量太少，可能观察不到气泡，因为稀盐酸先与未变质的______发生中和反应。","blanks":[["NaOH","氢氧化钠"]],"answer":["NaOH"],"explanation":"酸碱中和优先于酸与碳酸盐反应，必须加足量/过量稀盐酸。"},{"id":"kp-chemistry-sp-p07-06","subject":"chemistry","subjectLabel":"化学","knowledge":true,"kpId":"chemistry-sp-p07","kp":"氢氧化钠与生石灰变质程度探究（未变/部分/完全）","unit":"专题·实验探究与除杂鉴别","chapter":"专题与压轴 · 实验探究（变质/成分/除杂鉴别）压轴","source":"知识点精练 · 专题与压轴 · 氢氧化钠与生石灰变质程度探究（未变/部分/完全）（提高）","level":2,"kpFree":false,"type":"single","stem":"一包久置的生石灰（CaO）食品干燥剂，加水搅拌后放出大量热，过滤后向滤渣滴加稀盐酸产生气泡，说明该干燥剂中一定含有（ ）","options":[{"key":"A","text":"只有 CaO"},{"key":"B","text":"CaO 和 CaCO3（可能还含 Ca(OH)2）"},{"key":"C","text":"只有 CaCO3"},{"key":"D","text":"只有 Ca(OH)2"}],"answer":["B"],"explanation":"加水放大量热说明含 CaO；滤渣加酸产气说明含 CaCO3。"},{"id":"kp-chemistry-sp-p07-07","subject":"chemistry","subjectLabel":"化学","knowledge":true,"kpId":"chemistry-sp-p07","kp":"氢氧化钠与生石灰变质程度探究（未变/部分/完全）","unit":"专题·实验探究与除杂鉴别","chapter":"专题与压轴 · 实验探究（变质/成分/除杂鉴别）压轴","source":"知识点精练 · 专题与压轴 · 氢氧化钠与生石灰变质程度探究（未变/部分/完全）（拓展）","level":3,"kpFree":false,"type":"single","stem":"在“探究 NaOH 变质程度”第二步中，向除尽 Na2CO3 后的上层清液中，还可以滴加哪种试剂来代替酚酞检验 NaOH 的存在（ ）","options":[{"key":"A","text":"稀盐酸"},{"key":"B","text":"氯化钡溶液"},{"key":"C","text":"硫酸铜溶液（看是否产生蓝色沉淀）"},{"key":"D","text":"氯化钠溶液"}],"answer":["C"],"explanation":"CuSO4 与 NaOH 反应生成蓝色 Cu(OH)2 沉淀，可证明 OH⁻ 存在。"},{"id":"kp-chemistry-sp-p07-08","subject":"chemistry","subjectLabel":"化学","knowledge":true,"kpId":"chemistry-sp-p07","kp":"氢氧化钠与生石灰变质程度探究（未变/部分/完全）","unit":"专题·实验探究与除杂鉴别","chapter":"专题与压轴 · 实验探究（变质/成分/除杂鉴别）压轴","source":"知识点精练 · 专题与压轴 · 氢氧化钠与生石灰变质程度探究（未变/部分/完全）（拓展）","level":3,"kpFree":false,"type":"blank","stem":"为防止氢氧化钠和生石灰在空气中变质，实验室必须______保存。","blanks":[["密封"]],"answer":["密封"],"explanation":"隔绝空气中的水蒸气和二氧化碳。"},{"id":"kp-chemistry-sp-p07-09","subject":"chemistry","subjectLabel":"化学","knowledge":true,"kpId":"chemistry-sp-p07","kp":"氢氧化钠与生石灰变质程度探究（未变/部分/完全）","unit":"专题·实验探究与除杂鉴别","chapter":"专题与压轴 · 实验探究（变质/成分/除杂鉴别）压轴","source":"知识点精练 · 专题与压轴 · 氢氧化钠与生石灰变质程度探究（未变/部分/完全）（压轴解答）","level":3,"kpFree":false,"type":"essay","meta":"变质程度实验探究","stem":"实验室有一瓶敞口放置一段时间的 NaOH 溶液，同学们探究其变质情况。（1）写出 NaOH 溶液在空气中变质的化学方程式；（2）关于该溶液的变质程度，有哪三种合理猜想？（3）请设计实验证明该溶液为“部分变质”（写出步骤、试剂、现象和结论），并说明为什么不能用 Ca(OH)₂ 溶液代替 CaCl₂ 溶液。","score":10,"points":[{"text":"（1）2NaOH＋CO₂＝Na₂CO₃＋H₂O","score":2,"keys":["2NaOH","Na₂CO₃","Na2CO3"]},{"text":"（2）三种猜想：未变质（只有 NaOH）、部分变质（NaOH 和 Na₂CO₃）、完全变质（只有 Na₂CO₃）","score":2,"keys":["未变质","部分变质","完全变质"]},{"text":"（3）取样加过量 CaCl₂（或 BaCl₂）溶液产生白色沉淀（证含 Na₂CO₃ 并除尽），静置取清液滴酚酞变红（证含 NaOH）","score":4,"keys":["过量","CaCl₂","BaCl₂","白色沉淀","酚酞","变红"]},{"text":"不能用 Ca(OH)₂ 原因：Ca(OH)₂ 与 Na₂CO₃ 反应会生成 NaOH（引入 OH⁻），干扰原溶液中 NaOH 的检验","score":2,"keys":["生成NaOH","生成 NaOH","OH⁻","干扰"]}],"method":"① 检验部分变质＝同时证明“含 Na₂CO₃”和“含 NaOH”；② 关键难点：Na₂CO₃ 溶液也显碱性，会干扰 NaOH 检验！必须先加过量中性钙盐/钡盐（CaCl₂ 或 BaCl₂）把 CO₃²⁻ 彻底沉淀除尽，再用酚酞测上层清液是否仍显碱性；③ 不能加 Ca(OH)₂ 是因为反应会生成新的 NaOH 造成干扰。","sample":"解：（1）2NaOH＋CO₂＝Na₂CO₃＋H₂O。\n（2）三种猜想：\n① 未变质：溶质只有 NaOH；\n② 部分变质：溶质为 NaOH 和 Na₂CO₃；\n③ 完全变质：溶质只有 Na₂CO₃。\n（3）实验方案：\n取少量待测液于试管中，加入过量的 CaCl₂（或 BaCl₂）溶液，观察到有白色沉淀产生，证明含有 Na₂CO₃（且将 CO₃²⁻ 完全除去）；\n静置（或过滤）后，向上层清液中滴加无色酚酞溶液，溶液变红，证明含有 NaOH。\n由此得出结论：该 NaOH 溶液部分变质。\n不能用 Ca(OH)₂ 代替 CaCl₂ 的原因：Ca(OH)₂＋Na₂CO₃＝CaCO₃↓＋2NaOH，会生成新的 NaOH（且自身含 OH⁻），无法判断原溶液中是否含有 NaOH。","explanation":"阅卷必查的两个字：“过量”！写 CaCl₂ 溶液时如果不写“过量（或足量）”，无法保证 CO₃²⁻ 除尽，必扣 1～2 分。"},{"id":"kp-chemistry-sp-p08-01","subject":"chemistry","subjectLabel":"化学","knowledge":true,"kpId":"chemistry-sp-p08","kp":"反应后溶液中溶质成分猜想与验证","unit":"专题·实验探究与除杂鉴别","chapter":"专题与压轴 · 实验探究（变质/成分/除杂鉴别）压轴","source":"知识点精练 · 专题与压轴 · 反应后溶液中溶质成分猜想与验证（基础）","level":1,"kpFree":true,"type":"single","stem":"将稀盐酸与氢氧化钠溶液混合反应后，想检验反应后溶液中稀盐酸是否过量，下列试剂不可行的是（ ）","options":[{"key":"A","text":"碳酸钠溶液"},{"key":"B","text":"锌粒"},{"key":"C","text":"紫色石蕊溶液"},{"key":"D","text":"硝酸银溶液"}],"answer":["D"],"explanation":"生成物 NaCl 中也含有 Cl⁻，无论盐酸是否过量，滴加 AgNO3 都会产生 AgCl 白沉淀！"},{"id":"kp-chemistry-sp-p08-02","subject":"chemistry","subjectLabel":"化学","knowledge":true,"kpId":"chemistry-sp-p08","kp":"反应后溶液中溶质成分猜想与验证","unit":"专题·实验探究与除杂鉴别","chapter":"专题与压轴 · 实验探究（变质/成分/除杂鉴别）压轴","source":"知识点精练 · 专题与压轴 · 反应后溶液中溶质成分猜想与验证（基础）","level":1,"kpFree":true,"type":"single","stem":"向澄清石灰水中加入一定量碳酸钠溶液，充分反应后过滤。关于滤液中溶质成分的下列猜想，一定不合理的是（ ）","options":[{"key":"A","text":"NaOH、Ca(OH)2 和 Na2CO3"},{"key":"B","text":"只有 NaOH"},{"key":"C","text":"NaOH 和 Na2CO3"},{"key":"D","text":"NaOH 和 Ca(OH)2"}],"answer":["A"],"explanation":"Ca(OH)2 和 Na2CO3 会发生反应生成沉淀，绝不能同时存在于滤液中。"},{"id":"kp-chemistry-sp-p08-03","subject":"chemistry","subjectLabel":"化学","knowledge":true,"kpId":"chemistry-sp-p08","kp":"反应后溶液中溶质成分猜想与验证","unit":"专题·实验探究与除杂鉴别","chapter":"专题与压轴 · 实验探究（变质/成分/除杂鉴别）压轴","source":"知识点精练 · 专题与压轴 · 反应后溶液中溶质成分猜想与验证（基础）","level":1,"kpFree":true,"type":"single","stem":"要检验 Ca(OH)2 与 Na2CO3 反应过滤后的滤液中是否含有过量 Na2CO3，可向滤液中滴加足量（ ）","options":[{"key":"A","text":"无色酚酞"},{"key":"B","text":"稀盐酸（观察是否有气泡产生）"},{"key":"C","text":"氯化钠溶液"},{"key":"D","text":"氢氧化钠溶液"}],"answer":["B"],"explanation":"Na2CO3 遇足量稀盐酸产生 CO2 气泡，而 NaOH 和 Ca(OH)2 加酸无气泡。"},{"id":"kp-chemistry-sp-p08-04","subject":"chemistry","subjectLabel":"化学","knowledge":true,"kpId":"chemistry-sp-p08","kp":"反应后溶液中溶质成分猜想与验证","unit":"专题·实验探究与除杂鉴别","chapter":"专题与压轴 · 实验探究（变质/成分/除杂鉴别）压轴","source":"知识点精练 · 专题与压轴 · 反应后溶液中溶质成分猜想与验证（提高）","level":2,"kpFree":true,"kpDiag":true,"type":"single","stem":"实验室制取二氧化碳（CaCO3＋2HCl）反应结束后，向残留废液中滴加几滴紫色石蕊试液变红，则废液中含有的溶质是（ ）","options":[{"key":"A","text":"只有 HCl"},{"key":"B","text":"CaCl2 和 CaCO3"},{"key":"C","text":"CaCl2 和 HCl"},{"key":"D","text":"只有 CaCl2"}],"answer":["C"],"explanation":"石蕊变红说明稀盐酸过量，故溶质为生成物 CaCl2 和过量 HCl。"},{"id":"kp-chemistry-sp-p08-05","subject":"chemistry","subjectLabel":"化学","knowledge":true,"kpId":"chemistry-sp-p08","kp":"反应后溶液中溶质成分猜想与验证","unit":"专题·实验探究与除杂鉴别","chapter":"专题与压轴 · 实验探究（变质/成分/除杂鉴别）压轴","source":"知识点精练 · 专题与压轴 · 反应后溶液中溶质成分猜想与验证（提高）","level":2,"kpFree":false,"type":"blank","stem":"检验稀硫酸与 NaOH 反应后溶液中是否剩余 NaOH，可滴加无色酚酞溶液，若溶液变______色，说明 NaOH 过量。","blanks":[["红"]],"answer":["红"],"explanation":"Na2SO4 呈中性，酚酞变红即证明含过量 NaOH。"},{"id":"kp-chemistry-sp-p08-06","subject":"chemistry","subjectLabel":"化学","knowledge":true,"kpId":"chemistry-sp-p08","kp":"反应后溶液中溶质成分猜想与验证","unit":"专题·实验探究与除杂鉴别","chapter":"专题与压轴 · 实验探究（变质/成分/除杂鉴别）压轴","source":"知识点精练 · 专题与压轴 · 反应后溶液中溶质成分猜想与验证（提高）","level":2,"kpFree":false,"type":"single","stem":"若向反应后可能含 HCl 和 CaCl2 的废液中逐滴加入 Na2CO3 溶液，先观察到有气泡产生，过一会儿才产生白色沉淀，说明原废液中溶质为（ ）","options":[{"key":"A","text":"只有 CaCl2"},{"key":"B","text":"只有 HCl"},{"key":"C","text":"NaCl 和 CaCl2"},{"key":"D","text":"CaCl2 和 HCl"}],"answer":["D"],"explanation":"先与 HCl 反应产气，再与 CaCl2 反应生成 CaCO3 白沉淀，证明两者均存在。"},{"id":"kp-chemistry-sp-p08-07","subject":"chemistry","subjectLabel":"化学","knowledge":true,"kpId":"chemistry-sp-p08","kp":"反应后溶液中溶质成分猜想与验证","unit":"专题·实验探究与除杂鉴别","chapter":"专题与压轴 · 实验探究（变质/成分/除杂鉴别）压轴","source":"知识点精练 · 专题与压轴 · 反应后溶液中溶质成分猜想与验证（拓展）","level":3,"kpFree":false,"type":"single","stem":"用铁粉与稀硫酸反应制氢气后过滤，要证明滤液中稀硫酸有剩余，最直接且不引入新金属离子的试剂是（ ）","options":[{"key":"A","text":"氧化铜粉末或碳酸钠溶液"},{"key":"B","text":"无色酚酞"},{"key":"C","text":"氯化钡溶液"},{"key":"D","text":"硫酸铜溶液"}],"answer":["A"],"explanation":"BaCl2 会与 FeSO4 中的 SO4²⁻ 沉淀无法证明 H⁺；CuO 溶解变蓝或 Na2CO3 产气均可证明 H⁺ 剩余。"},{"id":"kp-chemistry-sp-p08-08","subject":"chemistry","subjectLabel":"化学","knowledge":true,"kpId":"chemistry-sp-p08","kp":"反应后溶液中溶质成分猜想与验证","unit":"专题·实验探究与除杂鉴别","chapter":"专题与压轴 · 实验探究（变质/成分/除杂鉴别）压轴","source":"知识点精练 · 专题与压轴 · 反应后溶液中溶质成分猜想与验证（拓展）","level":3,"kpFree":false,"type":"single","stem":"设计实验验证某猜想时，所选试剂必须能产生“唯一对应现象”。若检验某溶液中是否同时含 OH⁻ 和 CO3²⁻，应先加过量（ ）除去 CO3²⁻，再检验 OH⁻。","options":[{"key":"A","text":"稀盐酸"},{"key":"B","text":"氯化钡或氯化钙溶液"},{"key":"C","text":"氢氧化钡溶液"},{"key":"D","text":"酚酞溶液"}],"answer":["B"],"explanation":"用中性钡/钙盐沉淀除尽 CO3²⁻ 且不引入 OH⁻，再用酚酞检验原 OH⁻。"},{"id":"kp-chemistry-sp-p08-09","subject":"chemistry","subjectLabel":"化学","knowledge":true,"kpId":"chemistry-sp-p08","kp":"反应后溶液中溶质成分猜想与验证","unit":"专题·实验探究与除杂鉴别","chapter":"专题与压轴 · 实验探究（变质/成分/除杂鉴别）压轴","source":"知识点精练 · 专题与压轴 · 反应后溶液中溶质成分猜想与验证（压轴解答）","level":3,"kpFree":false,"type":"essay","meta":"溶质成分实验探究","stem":"同学们做稀盐酸与氢氧化钠溶液中和反应实验，向滴有酚酞的氢氧化钠溶液中逐滴加入稀盐酸至溶液恰好变为无色，再多滴了几滴。对反应后无色废液中的溶质成分展开探究：（1）写出反应后无色废液中溶质成分的两种合理猜想；（2）请选用两种不同类别的试剂，验证废液中含有稀盐酸（写出试剂名称与预期现象）；（3）有同学提出滴加 AgNO₃ 溶液产生白色沉淀就能证明含稀盐酸，请评价该方案是否正确并说明理由。","score":10,"points":[{"text":"（1）猜想一：只有 NaCl；猜想二：NaCl 和 HCl","score":3,"keys":["NaCl","HCl"]},{"text":"（2）任选两类不同试剂（如紫色石蕊变红、锌粒/铁粉冒气泡、Na₂CO₃/CaCO₃ 冒气泡、CuO 溶解变蓝等）且现象对应正确","score":4,"keys":["石蕊","锌","铁","碳酸钠","碳酸钙","气泡","变红"]},{"text":"（3）不正确；因为生成物 NaCl 中也含有 Cl⁻，滴加 AgNO₃ 溶液同样会产生 AgCl 白色沉淀，无法证明含 HCl","score":3,"keys":["不正确","错误","NaCl","Cl⁻","白色沉淀"]}],"method":"① 反应后溶质猜想铁律：一定有生成物 NaCl，可能有过量的某一种反应物（因为酚酞无色，排除 NaOH 过量，只剩恰好反应或 HCl 过量两种可能）；② 检验 HCl 本质是检验 H⁺，不同类别试剂可从指示剂、活泼金属、碳酸盐、金属氧化物中任选两类；③ AgNO₃ 检验的是 Cl⁻，生成物 NaCl 也含 Cl⁻。","sample":"解：（1）因酚酞呈无色，溶液中不含 NaOH，故合理猜想为：\n猜想一：只有 NaCl（恰好完全反应）；\n猜想二：NaCl 和 HCl（稀盐酸过量）。\n（2）验证含 HCl（即检验 H⁺）的两种不同类别试剂（任选其二）：\n① 酸碱指示剂：滴加紫色石蕊溶液，溶液变红；\n② 活泼金属：加入锌粒（或铁粉），有气泡产生；\n③ 碳酸盐：加入碳酸钠溶液（或大理石），有气泡产生；\n④ 金属氧化物：加入氧化铜粉末并微热，黑色固体溶解、溶液变蓝。\n（3）该方案不正确。因为无论是否含有稀盐酸，废液中一定含有生成物 NaCl，其中的 Cl⁻ 都会与 AgNO₃ 溶液反应生成白色的 AgCl 沉淀，不能证明 H⁺（即 HCl）的存在。","explanation":"审题抓关键词：“两种不同类别的试剂”！如果同时写锌粒和镁条（都属于金属）会被扣一半分数。"},{"id":"kp-chemistry-sp-p09-01","subject":"chemistry","subjectLabel":"化学","knowledge":true,"kpId":"chemistry-sp-p09","kp":"多步除杂、无试剂鉴别与气体净化顺序","unit":"专题·实验探究与除杂鉴别","chapter":"专题与压轴 · 实验探究（变质/成分/除杂鉴别）压轴","source":"知识点精练 · 专题与压轴 · 多步除杂、无试剂鉴别与气体净化顺序（基础）","level":1,"kpFree":true,"image":"./assets/knowledge/chemistry/sp/p09-gas.svg","type":"single","stem":"如图，要得到纯净干燥的 CO2（原气体混有 HCl 和 H2O），正确的试剂连接顺序是（ ）","options":[{"key":"A","text":"先通过浓硫酸，再通过饱和 NaHCO3 溶液"},{"key":"B","text":"先通过 NaOH 溶液，再通过浓硫酸"},{"key":"C","text":"先通过饱和 NaHCO3 溶液，再通过浓硫酸"},{"key":"D","text":"只通过澄清石灰水"}],"answer":["C"],"explanation":"除杂后除水；不能用 NaOH 否则吸收 CO2，先用饱和 NaHCO3 除 HCl 再用浓硫酸干燥。"},{"id":"kp-chemistry-sp-p09-02","subject":"chemistry","subjectLabel":"化学","knowledge":true,"kpId":"chemistry-sp-p09","kp":"多步除杂、无试剂鉴别与气体净化顺序","unit":"专题·实验探究与除杂鉴别","chapter":"专题与压轴 · 实验探究（变质/成分/除杂鉴别）压轴","source":"知识点精练 · 专题与压轴 · 多步除杂、无试剂鉴别与气体净化顺序（基础）","level":1,"kpFree":true,"type":"single","stem":"要检验某混合气体中是否同时含有水蒸气和二氧化碳，气体通过试剂的正确顺序是（ ）","options":[{"key":"A","text":"任意顺序均可"},{"key":"B","text":"先通过浓硫酸，再通过澄清石灰水"},{"key":"C","text":"先通过澄清石灰水，再通过无水硫酸铜"},{"key":"D","text":"先通过无水硫酸铜，再通过澄清石灰水"}],"answer":["D"],"explanation":"检验先验水！若先通澄清石灰水，气体会带出水蒸气干扰无水硫酸铜检验。"},{"id":"kp-chemistry-sp-p09-03","subject":"chemistry","subjectLabel":"化学","knowledge":true,"kpId":"chemistry-sp-p09","kp":"多步除杂、无试剂鉴别与气体净化顺序","unit":"专题·实验探究与除杂鉴别","chapter":"专题与压轴 · 实验探究（变质/成分/除杂鉴别）压轴","source":"知识点精练 · 专题与压轴 · 多步除杂、无试剂鉴别与气体净化顺序（基础）","level":1,"kpFree":true,"type":"single","stem":"不另加任何其他试剂，就能将下列四瓶失去标签的溶液一一鉴别出来的是（ ）","options":[{"key":"A","text":"CuSO4、NaOH、BaCl2、HCl"},{"key":"B","text":"H2SO4、HCl、NaCl、KNO3"},{"key":"C","text":"NaOH、KOH、NaCl、KCl"},{"key":"D","text":"NaCl、KCl、NaNO3、KNO3"}],"answer":["A"],"explanation":"先看颜色挑出蓝色 CuSO4；用 CuSO4 滴入其余三瓶，产生蓝沉淀是 NaOH、白沉淀是 BaCl2、无现象是 HCl！"},{"id":"kp-chemistry-sp-p09-04","subject":"chemistry","subjectLabel":"化学","knowledge":true,"kpId":"chemistry-sp-p09","kp":"多步除杂、无试剂鉴别与气体净化顺序","unit":"专题·实验探究与除杂鉴别","chapter":"专题与压轴 · 实验探究（变质/成分/除杂鉴别）压轴","source":"知识点精练 · 专题与压轴 · 多步除杂、无试剂鉴别与气体净化顺序（提高）","level":2,"kpFree":true,"kpDiag":true,"type":"single","stem":"除去下列物质中少量杂质（括号内为杂质），所选试剂和方法完全正确的是（ ）","options":[{"key":"A","text":"CaO（CaCO3）— 加足量水，过滤"},{"key":"B","text":"Cu 粉（Fe 粉）— 加足量稀盐酸，过滤"},{"key":"C","text":"CO2（CO）— 通入足量氧气点燃"},{"key":"D","text":"KCl 溶液（K2SO4）— 加过量 BaCl2 溶液，过滤"}],"answer":["B"],"explanation":"Fe 溶于稀盐酸而 Cu 不反应，过滤得纯 Cu；B 中 CaO 会与水反应；C 点不着；D 过量 BaCl2 引入新杂质。"},{"id":"kp-chemistry-sp-p09-05","subject":"chemistry","subjectLabel":"化学","knowledge":true,"kpId":"chemistry-sp-p09","kp":"多步除杂、无试剂鉴别与气体净化顺序","unit":"专题·实验探究与除杂鉴别","chapter":"专题与压轴 · 实验探究（变质/成分/除杂鉴别）压轴","source":"知识点精练 · 专题与压轴 · 多步除杂、无试剂鉴别与气体净化顺序（提高）","level":2,"kpFree":false,"type":"single","stem":"除去 CaO 中混有的少量 CaCO3，最简便合理的工业方法是（ ）","options":[{"key":"A","text":"加氢氧化钠溶液"},{"key":"B","text":"加稀盐酸"},{"key":"C","text":"高温煅烧"},{"key":"D","text":"加水过滤"}],"answer":["C"],"explanation":"CaCO3＝(高温)CaO＋CO2↑，直接转化为目标物 CaO 且无任何杂质残留。"},{"id":"kp-chemistry-sp-p09-06","subject":"chemistry","subjectLabel":"化学","knowledge":true,"kpId":"chemistry-sp-p09","kp":"多步除杂、无试剂鉴别与气体净化顺序","unit":"专题·实验探究与除杂鉴别","chapter":"专题与压轴 · 实验探究（变质/成分/除杂鉴别）压轴","source":"知识点精练 · 专题与压轴 · 多步除杂、无试剂鉴别与气体净化顺序（提高）","level":2,"kpFree":false,"type":"blank","stem":"用装有浓硫酸的洗气瓶干燥氧气时，气体应从______（填“长”或“短”）导管通入。","blanks":[["长"]],"answer":["长"],"explanation":"洗气遵循“长进短出”，让气体充分穿过干燥液。"},{"id":"kp-chemistry-sp-p09-07","subject":"chemistry","subjectLabel":"化学","knowledge":true,"kpId":"chemistry-sp-p09","kp":"多步除杂、无试剂鉴别与气体净化顺序","unit":"专题·实验探究与除杂鉴别","chapter":"专题与压轴 · 实验探究（变质/成分/除杂鉴别）压轴","source":"知识点精练 · 专题与压轴 · 多步除杂、无试剂鉴别与气体净化顺序（拓展）","level":3,"kpFree":false,"type":"single","stem":"要除去 FeSO4 溶液中混有的少量 CuSO4，最合适的操作是（ ）","options":[{"key":"A","text":"加入过量锌粉后过滤"},{"key":"B","text":"加入过量铜粉后过滤"},{"key":"C","text":"加入适量氢氧化钠溶液后过滤"},{"key":"D","text":"加入过量铁粉后过滤"}],"answer":["D"],"explanation":"Fe＋CuSO4＝FeSO4＋Cu，过量铁粉过滤即除，不引新杂。"},{"id":"kp-chemistry-sp-p09-08","subject":"chemistry","subjectLabel":"化学","knowledge":true,"kpId":"chemistry-sp-p09","kp":"多步除杂、无试剂鉴别与气体净化顺序","unit":"专题·实验探究与除杂鉴别","chapter":"专题与压轴 · 实验探究（变质/成分/除杂鉴别）压轴","source":"知识点精练 · 专题与压轴 · 多步除杂、无试剂鉴别与气体净化顺序（拓展）","level":3,"kpFree":false,"type":"single","stem":"下列各组白色固体，只用“水”就能一次性鉴别出来的是（ ）","options":[{"key":"A","text":"CaCO3、NaOH、NH4NO3、NaCl"},{"key":"B","text":"NaCl、KCl、KNO3"},{"key":"C","text":"Na2CO3、NaHCO3、NaOH"},{"key":"D","text":"BaSO4、CaCO3、AgCl"}],"answer":["A"],"explanation":"加水：CaCO3 不溶；NaOH 溶解剧烈放热；NH4NO3 溶解明显吸热降温；NaCl 溶解温度几乎不变。"},{"id":"kp-chemistry-sp-p10-01","subject":"chemistry","subjectLabel":"化学","knowledge":true,"kpId":"chemistry-sp-p10","kp":"复分解反应先后顺序与沉淀/气体拐点图像","unit":"专题·图像分析与综合计算","chapter":"专题与压轴 · 化学图像与综合计算压轴","source":"知识点精练 · 专题与压轴 · 复分解反应先后顺序与沉淀/气体拐点图像（基础）","level":1,"kpFree":true,"image":"./assets/knowledge/chemistry/sp/p10-graph.svg","type":"single","stem":"如图为向含有 HCl 和 CuCl2 的混合溶液中逐滴加入 NaOH 溶液的沉淀质量曲线，当滴加至 b 点时，溶液中的溶质是（ ）","options":[{"key":"A","text":"只有 NaCl"},{"key":"B","text":"NaCl 和 CuCl2"},{"key":"C","text":"NaCl、HCl 和 CuCl2"},{"key":"D","text":"NaCl 和 NaOH"}],"answer":["B"],"explanation":"b 点 HCl 恰好被中和完，CuCl2 尚未开始反应，故溶质为 NaCl 和 CuCl2。"},{"id":"kp-chemistry-sp-p10-02","subject":"chemistry","subjectLabel":"化学","knowledge":true,"kpId":"chemistry-sp-p10","kp":"复分解反应先后顺序与沉淀/气体拐点图像","unit":"专题·图像分析与综合计算","chapter":"专题与压轴 · 化学图像与综合计算压轴","source":"知识点精练 · 专题与压轴 · 复分解反应先后顺序与沉淀/气体拐点图像（基础）","level":1,"kpFree":true,"image":"./assets/knowledge/chemistry/sp/p10-graph.svg","type":"single","stem":"如图曲线中，当滴加 NaOH 溶液至 c 点（沉淀恰好达到最大）时，溶液的 pH 和溶质分别是（ ）","options":[{"key":"A","text":"pH＜7，NaCl 和 HCl"},{"key":"B","text":"pH＞7，NaCl 和 NaOH"},{"key":"C","text":"pH＝7，只有 NaCl"},{"key":"D","text":"pH＝7，NaCl 和 CuCl2"}],"answer":["C"],"explanation":"c 点 HCl 和 CuCl2 均恰好完全反应，溶质只有中性的 NaCl，pH＝7。"},{"id":"kp-chemistry-sp-p10-03","subject":"chemistry","subjectLabel":"化学","knowledge":true,"kpId":"chemistry-sp-p10","kp":"复分解反应先后顺序与沉淀/气体拐点图像","unit":"专题·图像分析与综合计算","chapter":"专题与压轴 · 化学图像与综合计算压轴","source":"知识点精练 · 专题与压轴 · 复分解反应先后顺序与沉淀/气体拐点图像（基础）","level":1,"kpFree":true,"type":"single","stem":"向含有 HCl 和 H2SO4 的混合溶液中逐滴加入 Ba(OH)2 溶液，产生白色沉淀的质量曲线起点在（ ）","options":[{"key":"A","text":"无沉淀产生"},{"key":"B","text":"横轴正半轴（延迟产生）"},{"key":"C","text":"纵轴正半轴"},{"key":"D","text":"原点（0 点，立刻产生沉淀）"}],"answer":["D"],"explanation":"BaSO4 沉淀不溶于强酸，故一滴入 Ba(OH)2 就立刻从原点开始生成白色沉淀。"},{"id":"kp-chemistry-sp-p10-04","subject":"chemistry","subjectLabel":"化学","knowledge":true,"kpId":"chemistry-sp-p10","kp":"复分解反应先后顺序与沉淀/气体拐点图像","unit":"专题·图像分析与综合计算","chapter":"专题与压轴 · 化学图像与综合计算压轴","source":"知识点精练 · 专题与压轴 · 复分解反应先后顺序与沉淀/气体拐点图像（提高）","level":2,"kpFree":true,"kpDiag":true,"type":"single","stem":"向一定量 NaOH 和 Na2CO3 混合溶液中逐滴加入稀盐酸，产生 CO2 气体的质量随加入稀盐酸质量变化的图像特点是（ ）","options":[{"key":"A","text":"先在横轴走一段水平线（0 气体），再斜向上升，最后变水平平台"},{"key":"B","text":"从原点立刻上升"},{"key":"C","text":"先上升后下降"},{"key":"D","text":"始终为 0"}],"answer":["A"],"explanation":"稀盐酸先中和 NaOH 无气体产生，中和完后才与 Na2CO3 反应产生 CO2。"},{"id":"kp-chemistry-sp-p10-05","subject":"chemistry","subjectLabel":"化学","knowledge":true,"kpId":"chemistry-sp-p10","kp":"复分解反应先后顺序与沉淀/气体拐点图像","unit":"专题·图像分析与综合计算","chapter":"专题与压轴 · 化学图像与综合计算压轴","source":"知识点精练 · 专题与压轴 · 复分解反应先后顺序与沉淀/气体拐点图像（提高）","level":2,"kpFree":false,"image":"./assets/knowledge/chemistry/sp/p10-graph.svg","type":"single","stem":"在如图的 d 点（NaOH 已过量），向此时溶液中滴加无色酚酞试液，溶液呈（ ）","options":[{"key":"A","text":"黄色"},{"key":"B","text":"红色"},{"key":"C","text":"蓝色"},{"key":"D","text":"无色"}],"answer":["B"],"explanation":"d 点含过量 NaOH，溶液显碱性，酚酞变红。"},{"id":"kp-chemistry-sp-p10-06","subject":"chemistry","subjectLabel":"化学","knowledge":true,"kpId":"chemistry-sp-p10","kp":"复分解反应先后顺序与沉淀/气体拐点图像","unit":"专题·图像分析与综合计算","chapter":"专题与压轴 · 化学图像与综合计算压轴","source":"知识点精练 · 专题与压轴 · 复分解反应先后顺序与沉淀/气体拐点图像（提高）","level":2,"kpFree":false,"type":"single","stem":"向盛有一定量 CaCl2 和 HCl 混合液的烧杯中逐滴加入 Na2CO3 溶液，溶液的 pH 变化趋势是（ ）","options":[{"key":"A","text":"一直上升"},{"key":"B","text":"一直下降"},{"key":"C","text":"先上升至 7（中和 HCl），在 7 处保持水平（与 CaCl2 沉淀），最后再上升大于 7（Na2CO3 过量）"},{"key":"D","text":"先降后升"}],"answer":["C"],"explanation":"中和 HCl 时 pH 升至 7；与 CaCl2 反应生成中性 NaCl 和沉淀，pH 维持在 7 平台；最后 Na2CO3 过量显碱性 pH＞7。"},{"id":"kp-chemistry-sp-p10-07","subject":"chemistry","subjectLabel":"化学","knowledge":true,"kpId":"chemistry-sp-p10","kp":"复分解反应先后顺序与沉淀/气体拐点图像","unit":"专题·图像分析与综合计算","chapter":"专题与压轴 · 化学图像与综合计算压轴","source":"知识点精练 · 专题与压轴 · 复分解反应先后顺序与沉淀/气体拐点图像（拓展）","level":3,"kpFree":false,"type":"single","stem":"向一定量氧化铁（Fe2O3）固体中逐滴加入稀盐酸至过量，溶液中铁元素质量随稀盐酸加入量的变化图像是（ ）","options":[{"key":"A","text":"先升后降"},{"key":"B","text":"从某正值开始下降"},{"key":"C","text":"始终为 0"},{"key":"D","text":"从 0 上升到定值后保持水平"}],"answer":["D"],"explanation":"原固体未溶解溶液含铁 0，加稀盐酸 Fe2O3 逐渐溶解为 FeCl3 溶液，完全溶解后铁元素质量不变。"},{"id":"kp-chemistry-sp-p10-08","subject":"chemistry","subjectLabel":"化学","knowledge":true,"kpId":"chemistry-sp-p10","kp":"复分解反应先后顺序与沉淀/气体拐点图像","unit":"专题·图像分析与综合计算","chapter":"专题与压轴 · 化学图像与综合计算压轴","source":"知识点精练 · 专题与压轴 · 复分解反应先后顺序与沉淀/气体拐点图像（拓展）","level":3,"kpFree":false,"type":"blank","stem":"在电解水实验中，生成氢气和氧气的质量比恒为 1∶8，若以通电时间为横坐标、气体质量为纵坐标，斜率较大的直线代表的是______（填“氧气”或“氢气”）。","blanks":[["氧气"]],"answer":["氧气"],"explanation":"相同时间内生成氧气质量是氢气的 8 倍，故氧气的质量曲线斜率更大。"},{"id":"kp-chemistry-sp-p10-09","subject":"chemistry","subjectLabel":"化学","knowledge":true,"kpId":"chemistry-sp-p10","kp":"复分解反应先后顺序与沉淀/气体拐点图像","unit":"专题·图像分析与综合计算","chapter":"专题与压轴 · 化学图像与综合计算压轴","source":"知识点精练 · 专题与压轴 · 复分解反应先后顺序与沉淀/气体拐点图像（压轴解答）","level":3,"kpFree":false,"type":"essay","meta":"复分解顺序与图像","stem":"向一定量 HCl 和 CaCl₂ 的混合溶液中逐滴加入 Na₂CO₃ 溶液至过量，测得生成沉淀的质量随加入 Na₂CO₃ 溶液质量变化分为三段：0→a 段无沉淀，a→b 段沉淀质量不断增加，b 点之后沉淀质量保持不变。（1）解释 0→a 段为什么没有沉淀产生，并写出该段反应的化学方程式；（2）写出 a→b 段反应的化学方程式；（3）指出 b 点时溶液的溶质成分，并描述从 0 到 b 点之后溶液 pH 的变化趋势。","score":10,"points":[{"text":"（1）0→a 段 Na₂CO₃ 先与 HCl 反应（即使生成 CaCO₃ 也会被 HCl 溶解），方程式 Na₂CO₃＋2HCl＝2NaCl＋H₂O＋CO₂↑","score":4,"keys":["HCl","2NaCl","CO₂↑","CO2"]},{"text":"（2）a→b 段：Na₂CO₃＋CaCl₂＝CaCO₃↓＋2NaCl","score":3,"keys":["CaCO₃↓","CaCO3","2NaCl"]},{"text":"（3）b 点溶质只有 NaCl；pH 变化：0→a 段由＜7 增大到 7，a→b 段保持 7 不变，b 点后继续增大至＞7","score":3,"keys":["NaCl","7","不变","增大"]}],"method":"① 混合溶液加碱或碳酸盐遵循“酸碱中和/酸反应优先”：0→a 段 Na₂CO₃ 先消耗 HCl 产生气体；② a 点 HCl 耗尽后，a→b 段 Na₂CO₃ 与 CaCl₂ 反应生成 CaCO₃ 沉淀；③ pH 变化呈“上升 → 平台（pH＝7）→ 再上升”三段阶梯。","sample":"解：（1）0→a 段 Na₂CO₃ 优先与混合液中的 HCl 发生反应（即便有 CaCO₃ 生成也会立刻被 HCl 溶解），因此此阶段只有气泡而无沉淀产生。\n化学方程式：Na₂CO₃＋2HCl＝2NaCl＋H₂O＋CO₂↑。\n（2）a 点时 HCl 恰好耗尽，a→b 段 Na₂CO₃ 与 CaCl₂ 反应产生沉淀：\nNa₂CO₃＋CaCl₂＝CaCO₃↓＋2NaCl。\n（3）b 点时 CaCl₂ 恰好完全反应，溶液中溶质只有 NaCl（溶液呈中性，pH＝7）。\n溶液 pH 变化趋势：0→a 段随盐酸消耗 pH 从小于 7 逐渐升高至 7；a→b 段生成中性 NaCl 与沉淀，pH 保持 7 不变（呈水平平台）；b 点之后过量 Na₂CO₃ 显碱性，pH 继续升高至大于 7。","explanation":"该模型几乎是各地中考图像题必考原型，牢记“三段对应关系”：0→a 产气 pH 升，a→b 产沉淀 pH 平，b 后过量 pH 再升！"},{"id":"kp-chemistry-sp-p11-01","subject":"chemistry","subjectLabel":"化学","knowledge":true,"kpId":"chemistry-sp-p11","kp":"元素守恒法与差量法巧解化学计算","unit":"专题·图像分析与综合计算","chapter":"专题与压轴 · 化学图像与综合计算压轴","source":"知识点精练 · 专题与压轴 · 元素守恒法与差量法巧解化学计算（基础）","level":1,"kpFree":true,"type":"blank","stem":"某氧化铁（Fe2O3）和四氧化三铁（Fe3O4）的混合物 20 g，经足量 CO 高温完全还原后得到 14.4 g 纯铁，则原混合物中氧元素的质量为______g。","blanks":[["5.6"]],"answer":["5.6"],"explanation":"混合物仅含 Fe 和 O，故 m(O)＝20－14.4＝5.6 g。"},{"id":"kp-chemistry-sp-p11-02","subject":"chemistry","subjectLabel":"化学","knowledge":true,"kpId":"chemistry-sp-p11","kp":"元素守恒法与差量法巧解化学计算","unit":"专题·图像分析与综合计算","chapter":"专题与压轴 · 化学图像与综合计算压轴","source":"知识点精练 · 专题与压轴 · 元素守恒法与差量法巧解化学计算（基础）","level":1,"kpFree":true,"type":"blank","stem":"将 25 g 石灰石样品（杂质不反应）放入 100 g 足量稀盐酸中充分反应，称得烧杯内剩余物质总质量为 116.2 g，则生成二氧化碳的质量为______g。","blanks":[["8.8"]],"answer":["8.8"],"explanation":"由差量法，m(CO2)＝25＋100－116.2＝8.8 g。"},{"id":"kp-chemistry-sp-p11-03","subject":"chemistry","subjectLabel":"化学","knowledge":true,"kpId":"chemistry-sp-p11","kp":"元素守恒法与差量法巧解化学计算","unit":"专题·图像分析与综合计算","chapter":"专题与压轴 · 化学图像与综合计算压轴","source":"知识点精练 · 专题与压轴 · 元素守恒法与差量法巧解化学计算（基础）","level":1,"kpFree":true,"type":"blank","stem":"某镁粉和氧化镁的混合物共 10 g，其中氧元素质量分数为 20%，将它与足量稀硫酸完全反应后蒸发，最终得到硫酸镁（MgSO4）的质量为______g（Mg-24, S-32, O-16）。","blanks":[["40"]],"answer":["40"],"explanation":"镁元素质量＝10×(1－20%)＝8 g；MgSO4 中 Mg 占 24/120＝20%，故 m(MgSO4)＝8÷20%＝40 g！"},{"id":"kp-chemistry-sp-p11-04","subject":"chemistry","subjectLabel":"化学","knowledge":true,"kpId":"chemistry-sp-p11","kp":"元素守恒法与差量法巧解化学计算","unit":"专题·图像分析与综合计算","chapter":"专题与压轴 · 化学图像与综合计算压轴","source":"知识点精练 · 专题与压轴 · 元素守恒法与差量法巧解化学计算（提高）","level":2,"kpFree":true,"kpDiag":true,"type":"single","stem":"某样品由 CaCO3 和 CaO 组成，测得其中钙元素的质量分数为 50%，取 20 g 该样品高温充分煅烧至质量不再变化，最终剩余固体（CaO）的质量为（ ）","options":[{"key":"A","text":"14 g"},{"key":"B","text":"18 g"},{"key":"C","text":"16 g"},{"key":"D","text":"10 g"}],"answer":["A"],"explanation":"钙元素质量＝20×50%＝10 g；最终全为 CaO（含钙 40/56＝5/7），故 m(CaO)＝10÷(5/7)＝14 g！"},{"id":"kp-chemistry-sp-p11-05","subject":"chemistry","subjectLabel":"化学","knowledge":true,"kpId":"chemistry-sp-p11","kp":"元素守恒法与差量法巧解化学计算","unit":"专题·图像分析与综合计算","chapter":"专题与压轴 · 化学图像与综合计算压轴","source":"知识点精练 · 专题与压轴 · 元素守恒法与差量法巧解化学计算（提高）","level":2,"kpFree":false,"type":"blank","stem":"将一根质量为 50 g 的铁棒插入足量 CuSO4 溶液中，一段时间后取出洗净烘干称重为 50.8 g，则析出金属铜的质量为______g（Fe-56, Cu-64）。","blanks":[["6.4"]],"answer":["6.4"],"explanation":"Fe(56)换Cu(64)每析出 64 g Cu 增重 8 g；现增重 0.8 g，故析出铜 6.4 g。"},{"id":"kp-chemistry-sp-p11-06","subject":"chemistry","subjectLabel":"化学","knowledge":true,"kpId":"chemistry-sp-p11","kp":"元素守恒法与差量法巧解化学计算","unit":"专题·图像分析与综合计算","chapter":"专题与压轴 · 化学图像与综合计算压轴","source":"知识点精练 · 专题与压轴 · 元素守恒法与差量法巧解化学计算（提高）","level":2,"kpFree":false,"type":"single","stem":"在 10 g 碳酸钙和碳酸钠的混合物中加入足量稀盐酸，完全反应后可能生成 CO2 的质量是（CaCO3-100, Na2CO3-106, CO2-44）（ ）","options":[{"key":"A","text":"4.0 g"},{"key":"B","text":"4.3 g"},{"key":"C","text":"4.5 g"},{"key":"D","text":"5.0 g"}],"answer":["B"],"explanation":"极值法：10 g 纯 CaCO3 产 4.4 g CO2，10 g 纯 Na2CO3 产 4.15 g CO2，混合物必介于 4.15～4.4 g 之间，选 4.3 g。"},{"id":"kp-chemistry-sp-p11-07","subject":"chemistry","subjectLabel":"化学","knowledge":true,"kpId":"chemistry-sp-p11","kp":"元素守恒法与差量法巧解化学计算","unit":"专题·图像分析与综合计算","chapter":"专题与压轴 · 化学图像与综合计算压轴","source":"知识点精练 · 专题与压轴 · 元素守恒法与差量法巧解化学计算（拓展）","level":3,"kpFree":false,"type":"blank","stem":"某有机物 3.2 g 完全燃烧生成 4.4 g CO2 和 3.6 g H2O，则该有机物中碳、氢、氧三种元素的质量比为______（最简整数比）。","blanks":[["3:1:4","3∶1∶4"]],"answer":["3:1:4"],"explanation":"m(C)＝1.2 g，m(H)＝0.4 g，m(O)＝3.2－1.2－0.4＝1.6 g，比值 1.2∶0.4∶1.6＝3∶1∶4。"},{"id":"kp-chemistry-sp-p11-08","subject":"chemistry","subjectLabel":"化学","knowledge":true,"kpId":"chemistry-sp-p11","kp":"元素守恒法与差量法巧解化学计算","unit":"专题·图像分析与综合计算","chapter":"专题与压轴 · 化学图像与综合计算压轴","source":"知识点精练 · 专题与压轴 · 元素守恒法与差量法巧解化学计算（拓展）","level":3,"kpFree":false,"type":"single","stem":"5.6 g 含杂质的铁粉与足量稀硫酸反应，生成 0.22 g 氢气（纯 5.6 g 铁只产 0.2 g 氢气），则所含杂质可能是（ ）","options":[{"key":"A","text":"碳（不反应）"},{"key":"B","text":"锌（相对原子质量 65）"},{"key":"C","text":"铝或镁（等质量产氢比铁多）"},{"key":"D","text":"铜（不反应）"}],"answer":["C"],"explanation":"杂质必须比铁产氢能力更强，Mg(24)和 Al(27/3×2＝18)等质量产氢均多于 Fe(56)。"},{"id":"national-fj-2026-chemistry-q18","national":true,"subject":"chemistry","subjectLabel":"化学","paperId":"fj-2026-chemistry","number":18,"section":"非选择题","chapter":"2026 年福建中考化学","grade":"九下","stage":"9-down","source":"2026 年福建中考化学 第 18 题","type":"essay","meta":"非选择题","material":"","stem":"（6 分）某检测机构利用下列反应测定食品添加剂葡萄糖酸钙样品中氯化物（以 NaCl 计）的含量：NaCl＋AgNO₃ ═ AgCl↓＋NaNO₃。结果表明，2.00 g 样品参加反应，生成 AgCl 2.87 mg。（相对原子质量：Na 23，Cl 35.5，Ag 108）\n(1) 计算 2.00 g 样品中 NaCl 的质量（写出计算过程）。\n(2) 依据食品安全国家标准，葡萄糖酸钙中氯化物（以 NaCl 计）的含量应低于 0.08%。结合计算结果判断，该样品中氯化物的含量______（填“符合”或“不符合”）国家标准。","points":[{"text":"(1) 设 NaCl 质量为 x，写对比例式 58.5/143.5＝x/2.87 mg","score":3,"keys":[]},{"text":"解得 x＝1.17 mg，格式完整（设、写方程式、列比例、求解、答）","score":2,"keys":[]},{"text":"(2) 符合（1.17 mg÷2 000 mg×100%≈0.059%＜0.08%）","score":1,"keys":[]}],"score":6,"sample":"(1) 解：设 2.00 g 样品中 NaCl 的质量为 x。\nNaCl＋AgNO₃ ═ AgCl↓＋NaNO₃\n58.5　　　　 143.5\nx　　　　　　2.87 mg\n58.5/143.5＝x/2.87 mg，x＝1.17 mg。\n答：2.00 g 样品中 NaCl 的质量为 1.17 mg。\n(2) 符合。","method":"设未知数 → 写化学方程式 → 找相关物质的相对分子质量和已知量 → 列比例式 → 求解 → 答。","answer":[],"explanation":"NaCl 相对分子质量 23＋35.5＝58.5，AgCl 为 108＋35.5＝143.5。含量＝1.17 mg÷2 000 mg×100%≈0.059%，低于 0.08%，符合。坑点：mg 和 g 混用，2.00 g＝2 000 mg。（本题官方答案页未收入合订本，以上按题给数据演算。）","kp":"根据化学方程式的计算","kpId":"chemistry-sp-p11","kpRef":true},{"id":"national-jx-2026-chemistry-q20","national":true,"subject":"chemistry","subjectLabel":"化学","paperId":"jx-2026-chemistry","number":20,"section":"综合计算题","chapter":"2026 年江西中考化学","grade":"九下","stage":"9-down","source":"2026 年江西中考化学 第 20 题","type":"essay","meta":"综合计算题","material":"","stem":"（10 分）氢气在氯气中燃烧生成氯化氢的反应（H₂＋Cl₂ ═点燃═ 2HCl）可用于工业制备盐酸。（相对原子质量：H 1，Cl 35.5）\n(1) 该反应的基本反应类型为______。\n(2) 计算 10 kg 氢气完全反应生成氯化氢的质量（写出计算过程）。\n(3) 将 37 kg 氯化氢气体完全溶解于 63 kg 水中，所得溶液中溶质的质量分数为______。\n(4) 在实验室中，用浓盐酸配制一定溶质质量分数的稀盐酸，混匀时玻璃棒的作用是______，若操作均正确，最终得到的稀盐酸中溶质的质量分数偏小的原因可能为______。","points":[{"text":"(1) 化合反应","score":1,"keys":[]},{"text":"(2) 设未知数、写方程式、找出 2 与 73 的关系","score":2,"keys":[]},{"text":"列比例式 2/73＝10 kg/x，解得 x＝365 kg，作答","score":3,"keys":[]},{"text":"(3) 37%","score":2,"keys":[]},{"text":"(4) 搅拌，使液体混合均匀","score":1,"keys":[]},{"text":"盐酸挥发，使溶质减少","score":1,"keys":[]}],"score":10,"sample":"(1) 化合反应。\n(2) 解：设生成氯化氢的质量为 x。\nH₂＋Cl₂ ═点燃═ 2HCl\n2　　　　　　 73\n10 kg　　　　 x\n2/73＝10 kg/x，x＝365 kg。\n答：完全反应生成氯化氢的质量为 365 kg。\n(3) 37%。\n(4) 搅拌，使液体混合均匀；盐酸挥发，使溶质减少。","method":"设未知数 → 写化学方程式 → 找相关物质的质量关系 → 列比例式 → 求解 → 答。","answer":[],"explanation":"2HCl 的相对质量是 2×36.5＝73。(3) 37÷(37＋63)×100%＝37%。浓盐酸有挥发性，HCl 跑掉，浓度偏小。","kp":"根据化学方程式的计算","kpId":"chemistry-sp-p11","kpRef":true},{"id":"kp-chemistry-sp-p12-01","subject":"chemistry","subjectLabel":"化学","knowledge":true,"kpId":"chemistry-sp-p12","kp":"溶液反应后所得溶液溶质质量分数综合计算","unit":"专题·图像分析与综合计算","chapter":"专题与压轴 · 化学图像与综合计算压轴","source":"知识点精练 · 专题与压轴 · 溶液反应后所得溶液溶质质量分数综合计算（基础）","level":1,"kpFree":true,"type":"blank","stem":"将 10.6 g 碳酸钠固体完全溶解在 93.8 g 稀盐酸中恰好完全反应（Na2CO3＋2HCl＝2NaCl＋H2O＋CO2↑，Na2CO3-106, NaCl-58.5, CO2-44），生成 CO2 质量为 4.4 g，则反应后所得溶液的质量为______g。","blanks":[["100"]],"answer":["100"],"explanation":"m液后＝10.6＋93.8－4.4＝100 g。"},{"id":"kp-chemistry-sp-p12-02","subject":"chemistry","subjectLabel":"化学","knowledge":true,"kpId":"chemistry-sp-p12","kp":"溶液反应后所得溶液溶质质量分数综合计算","unit":"专题·图像分析与综合计算","chapter":"专题与压轴 · 化学图像与综合计算压轴","source":"知识点精练 · 专题与压轴 · 溶液反应后所得溶液溶质质量分数综合计算（基础）","level":1,"kpFree":true,"type":"blank","stem":"将 10.6 g 碳酸钠固体与 93.8 g 稀盐酸恰好完全反应，生成 11.7 g NaCl 和 4.4 g CO2，则反应后所得氯化钠溶液的溶质质量分数为______%。","blanks":[["11.7"]],"answer":["11.7"],"explanation":"m液后＝100 g，ω＝11.7÷100×100%＝11.7%。"},{"id":"kp-chemistry-sp-p12-03","subject":"chemistry","subjectLabel":"化学","knowledge":true,"kpId":"chemistry-sp-p12","kp":"溶液反应后所得溶液溶质质量分数综合计算","unit":"专题·图像分析与综合计算","chapter":"专题与压轴 · 化学图像与综合计算压轴","source":"知识点精练 · 专题与压轴 · 溶液反应后所得溶液溶质质量分数综合计算（基础）","level":1,"kpFree":true,"type":"blank","stem":"把 10 g 含杂质的石灰石样品（含 CaCO3 80%，杂质不溶也不反应）加入 95.52 g 稀盐酸中恰好完全反应，生成 3.52 g CO2，则反应后滤液的质量为______g。","blanks":[["100"]],"answer":["100"],"explanation":"纯 CaCO3 8 g（杂质 2 g 不进溶液），m液后＝8＋95.52－3.52＝100 g！"},{"id":"kp-chemistry-sp-p12-04","subject":"chemistry","subjectLabel":"化学","knowledge":true,"kpId":"chemistry-sp-p12","kp":"溶液反应后所得溶液溶质质量分数综合计算","unit":"专题·图像分析与综合计算","chapter":"专题与压轴 · 化学图像与综合计算压轴","source":"知识点精练 · 专题与压轴 · 溶液反应后所得溶液溶质质量分数综合计算（提高）","level":2,"kpFree":true,"kpDiag":true,"type":"single","stem":"向 100 g 质量分数为 10% 的 NaOH 溶液中加入 100 g 稀盐酸恰好完全中和，反应后所得溶液的质量是（ ）","options":[{"key":"A","text":"190 g"},{"key":"B","text":"100 g"},{"key":"C","text":"180 g"},{"key":"D","text":"200 g"}],"answer":["D"],"explanation":"中和反应无气体和沉淀生成，故反应后溶液质量直接等于 100＋100＝200 g。"},{"id":"kp-chemistry-sp-p12-05","subject":"chemistry","subjectLabel":"化学","knowledge":true,"kpId":"chemistry-sp-p12","kp":"溶液反应后所得溶液溶质质量分数综合计算","unit":"专题·图像分析与综合计算","chapter":"专题与压轴 · 化学图像与综合计算压轴","source":"知识点精练 · 专题与压轴 · 溶液反应后所得溶液溶质质量分数综合计算（提高）","level":2,"kpFree":false,"type":"blank","stem":"将 5.6 g 铁粉加入 94.6 g 稀硫酸中恰好完全反应，生成 0.2 g H2 和 15.2 g FeSO4，则反应后所得硫酸亚铁溶液的溶质质量分数为______%。","blanks":[["15.2"]],"answer":["15.2"],"explanation":"m液后＝5.6＋94.6－0.2＝100 g，ω＝15.2÷100×100%＝15.2%。"},{"id":"kp-chemistry-sp-p12-06","subject":"chemistry","subjectLabel":"化学","knowledge":true,"kpId":"chemistry-sp-p12","kp":"溶液反应后所得溶液溶质质量分数综合计算","unit":"专题·图像分析与综合计算","chapter":"专题与压轴 · 化学图像与综合计算压轴","source":"知识点精练 · 专题与压轴 · 溶液反应后所得溶液溶质质量分数综合计算（提高）","level":2,"kpFree":false,"type":"blank","stem":"将含 NaCl 和 Na2CO3 的固体混合物 20 g（其中 Na2CO3 为 10.6 g）加入 84.4 g 稀盐酸中恰好完全反应，生成 11.7 g NaCl 和 4.4 g CO2，则所得溶液中 NaCl 的溶质质量分数为______%。","blanks":[["21.1"]],"answer":["21.1"],"explanation":"原有 NaCl＝20－10.6＝9.4 g，总溶质＝9.4＋11.7＝21.1 g；m液后＝20＋84.4－4.4＝100 g；ω＝21.1%。"},{"id":"kp-chemistry-sp-p12-07","subject":"chemistry","subjectLabel":"化学","knowledge":true,"kpId":"chemistry-sp-p12","kp":"溶液反应后所得溶液溶质质量分数综合计算","unit":"专题·图像分析与综合计算","chapter":"专题与压轴 · 化学图像与综合计算压轴","source":"知识点精练 · 专题与压轴 · 溶液反应后所得溶液溶质质量分数综合计算（拓展）","level":3,"kpFree":false,"type":"blank","stem":"向 100 g 质量分数为 16% 的 CuSO4 溶液中加入 109.8 g NaOH 溶液恰好完全反应（CuSO4-160, Cu(OH)2-98, Na2SO4-142），生成 9.8 g Cu(OH)2 沉淀和 14.2 g Na2SO4，则反应后滤液的溶质质量分数为______%。","blanks":[["7.1"]],"answer":["7.1"],"explanation":"m液后＝100＋109.8－9.8＝200 g，ω＝14.2÷200×100%＝7.1%。"},{"id":"kp-chemistry-sp-p12-08","subject":"chemistry","subjectLabel":"化学","knowledge":true,"kpId":"chemistry-sp-p12","kp":"溶液反应后所得溶液溶质质量分数综合计算","unit":"专题·图像分析与综合计算","chapter":"专题与压轴 · 化学图像与综合计算压轴","source":"知识点精练 · 专题与压轴 · 溶液反应后所得溶液溶质质量分数综合计算（拓展）","level":3,"kpFree":false,"type":"single","stem":"在计算“反应后所得溶液的溶质质量分数”时，下列哪一项绝对不能算入“反应后溶液质量”中（ ）","options":[{"key":"A","text":"原混合物中未反应的难溶性杂质质量"},{"key":"B","text":"原有且未参加反应的可溶性溶质质量"},{"key":"C","text":"溶剂水的质量"},{"key":"D","text":"新生成的可溶性溶质质量"}],"answer":["A"],"explanation":"难溶性杂质不溶解在水中，必须从溶液总质量中扣除。"},{"id":"kp-chemistry-sp-p12-09","subject":"chemistry","subjectLabel":"化学","knowledge":true,"kpId":"chemistry-sp-p12","kp":"溶液反应后所得溶液溶质质量分数综合计算","unit":"专题·图像分析与综合计算","chapter":"专题与压轴 · 化学图像与综合计算压轴","source":"知识点精练 · 专题与压轴 · 溶液反应后所得溶液溶质质量分数综合计算（压轴解答）","level":3,"kpFree":false,"type":"essay","meta":"溶液质量分数计算","stem":"称取 12.5 g 石灰石样品（杂质不溶于水，也不与稀盐酸反应）放入烧杯中，加入 100 g 稀盐酸恰好完全反应，测得反应后烧杯内剩余物质总质量为 108.1 g。（相对原子质量：Ca-40，C-12，O-16，Cl-35.5）求：（1）反应生成 CO₂ 的质量；（2）样品中 CaCO₃ 的质量分数；（3）反应后过滤所得滤液中溶质的质量分数（结果精确到 0.1%）。","score":10,"points":[{"text":"（1）由质量守恒得 m(CO₂)＝12.5 g＋100 g－108.1 g＝4.4 g","score":2,"keys":["4.4"]},{"text":"（2）列方程式 CaCO₃＋2HCl＝CaCl₂＋H₂O＋CO₂↑，解得 m(CaCO₃)＝10 g，质量分数 10/12.5＝80%","score":4,"keys":["10","80%"]},{"text":"（3）解得 m(CaCl₂)＝11.1 g，滤液质量＝10＋100－4.4＝105.6 g（或 108.1－2.5），溶质质量分数＝11.1/105.6≈10.5%","score":4,"keys":["11.1","105.6","10.5%"]}],"method":"① 质量守恒差量法秒算气体质量：m(CO₂)＝反应前总质量－反应后总质量；② 由化学方程式按比例同时求出参加反应的 CaCO₃ 质量和生成的 CaCl₂ 质量；③ 算滤液总质量务必减掉“不溶性杂质”和“逸出的气体”！","sample":"解：（1）根据质量守恒定律，生成 CO₂ 的质量：\nm(CO₂)＝12.5 g＋100 g－108.1 g＝4.4 g。\n（2）设样品中 CaCO₃ 的质量为 x，生成 CaCl₂ 的质量为 y。\nCaCO₃ ＋ 2HCl ＝ CaCl₂ ＋ H₂O ＋ CO₂↑\n 100              111            44\n  x                y             4.4 g\n100/x＝44/4.4 g，解得 x＝10 g；\n111/y＝44/4.4 g，解得 y＝11.1 g。\n样品中 CaCO₃ 的质量分数＝(10 g / 12.5 g)×100%＝80%。\n（3）样品中不溶性杂质质量＝12.5 g－10 g＝2.5 g。\n反应后过滤所得滤液质量＝10 g＋100 g－4.4 g＝105.6 g（或 108.1 g－2.5 g＝105.6 g）。\n滤液中溶质的质量分数＝(11.1 g / 105.6 g)×100%≈10.5%。\n答：（1）生成 CO₂ 4.4 g；（2）CaCO₃ 质量分数为 80%；（3）滤液中溶质的质量分数约为 10.5%。","explanation":"化学综合计算头号雷区：算滤液质量时错用 108.1 g（忘了减去 2.5 g 不溶杂质）！记住口诀：溶液质量＝参加反应固体＋加入液体－气体－沉淀。"}]};
